Save this as `index.html`. It’s a complete single-file racer with a closed track, a chase camera, and a best lap that persists in the same browser. Three.js loads from a CDN, so the page needs an internet connection.

**Controls:** WASD or arrow keys to drive, **R** to restart the current lap. Drive through the checkpoints in order to record a lap; the finish line alone doesn’t count.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Pine Loop Racer</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; overflow: hidden; background: #a6d7ec; }
    canvas { display: block; }
    #hud {
      position: fixed; top: 16px; left: 16px; z-index: 1;
      padding: 14px 18px; border-radius: 12px;
      background: #14232dea; color: #fff;
      font: 15px/1.6 system-ui, sans-serif;
      font-variant-numeric: tabular-nums;
      pointer-events: none;
    }
    h1 { margin: 0 0 5px; font-size: 19px; }
    #status { color: #ffda87; }
    small { color: #bfd1da; }
  </style>
</head>
<body>
  <div id="hud">
    <h1>Pine Loop Racer</h1>
    <div>Lap: <strong id="lap">0.00 s</strong></div>
    <div>Best: <strong id="best">—</strong></div>
    <div id="status">Cross the start line</div>
    <small>WASD / arrows · R to restart</small>
  </div>

  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa6d7ec);
    scene.fog = new THREE.Fog(0xa6d7ec, 100, 230);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    const camera = new THREE.PerspectiveCamera(62, 1, 0.1, 300);
    function resize() {
      renderer.setSize(innerWidth, innerHeight);
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
    }
    addEventListener('resize', resize);
    resize();

    scene.add(new THREE.HemisphereLight(0xfff4de, 0x809c74, 2.2));
    const sun = new THREE.DirectionalLight(0xffe4bb, 2.5);
    sun.position.set(-40, 65, 25);
    scene.add(sun);

    const mat = color => new THREE.MeshStandardMaterial({
      color, flatShading: true
    });
    function box(w, h, d, material, parent, x, y, z) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
      mesh.position.set(x, y, z);
      parent.add(mesh);
      return mesh;
    }

    box(420, 0.4, 420, mat(0x79a65e), scene, 0, -0.22, 0);

    const curve = new THREE.CatmullRomCurve3([
      [-42, -23], [-10, -34], [32, -30], [52, -8], [40, 25],
      [13, 33], [-7, 18], [-35, 31], [-53, 12]
    ].map(([x, z]) => new THREE.Vector3(x, 0, z)), true);

    const N = 320;
    const halfRoad = 5;
    const samples = Array.from({ length: N }, (_, i) => {
      const u = i / N;
      const point = curve.getPointAt(u);
      const tangent = curve.getTangentAt(u).normalize();
      const side = new THREE.Vector3(tangent.z, 0, -tangent.x);
      return { point, tangent, side };
    });

    function strip(left, right, y, material) {
      const positions = [], indices = [];
      for (let i = 0; i <= N; i++) {
        const { point, side } = samples[i % N];
        for (const offset of [left, right]) {
          positions.push(point.x + side.x * offset, y, point.z + side.z * offset);
        }
        if (i < N) {
          const a = i * 2;
          indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
        }
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geometry.setIndex(indices);
      geometry.computeVertexNormals();
      scene.add(new THREE.Mesh(geometry, material));
    }

    strip(-5.45, 5.45, 0.015, mat(0xe6d5ad));
    strip(-halfRoad, halfRoad, 0.03, mat(0x40474e));
    strip(-4.8, -4.68, 0.042, mat(0xece9d7));
    strip(4.68, 4.8, 0.042, mat(0xece9d7));

    const gateIndices = [0, 80, 160, 240];
    function trackGroup(index) {
      const { point, tangent } = samples[index];
      const group = new THREE.Group();
      group.position.copy(point);
      group.rotation.y = Math.atan2(tangent.x, tangent.z);
      scene.add(group);
      return group;
    }

    const white = mat(0xf9efd8), black = mat(0x24292c);
    const start = trackGroup(0);
    for (let col = 0; col < 10; col++) {
      for (let row = 0; row < 2; row++) {
        box(1, 0.018, 0.55, (col + row) % 2 ? white : black,
            start, col - 4.5, 0.049, (row - 0.5) * 0.55);
      }
    }

    const orange = mat(0xffa62b);
    for (const index of gateIndices) {
      const group = trackGroup(index);
      for (const x of [-5.65, 5.65]) {
        box(0.35, 1.7, 0.35, orange, group, x, 0.85, 0);
        box(0.42, 0.22, 0.42, white, group, x, 1.5, 0);
      }
    }

    function roadDistanceSq(x, z) {
      let best = Infinity;
      for (let i = 0; i < N; i++) {
        const a = samples[i].point;
        const b = samples[(i + 1) % N].point;
        const dx = b.x - a.x, dz = b.z - a.z;
        const t = THREE.MathUtils.clamp(
          ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz), 0, 1
        );
        const ex = x - (a.x + t * dx), ez = z - (a.z + t * dz);
        best = Math.min(best, ex * ex + ez * ez);
      }
      return best;
    }

    let seed = 717;
    function random() {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed / 4294967296;
    }
    const bark = mat(0x80553c);
    const greens = [mat(0x305d44), mat(0x398058), mat(0x4c8f55)];
    const pine = new THREE.ConeGeometry(1, 2.6, 5);
    for (let i = 0; i < 200; i++) {
      const x = (random() - 0.5) * 175;
      const z = (random() - 0.5) * 145;
      if (roadDistanceSq(x, z) < 8 ** 2) continue;
      const s = 0.75 + random() * 1.25;
      box(0.32 * s, 1.4 * s, 0.32 * s, bark, scene, x, 0.7 * s, z);
      const crown = new THREE.Mesh(pine, greens[i % greens.length]);
      crown.position.set(x, 2.2 * s, z);
      crown.scale.setScalar(s);
      crown.rotation.y = random() * Math.PI;
      scene.add(crown);
    }

    const car = new THREE.Group();
    scene.add(car);
    const red = mat(0xe34135);
    box(1.75, 0.48, 3.15, red, car, 0, 0.53, 0);
    box(1.32, 0.43, 1.38, mat(0x274454), car, 0, 0.94, -0.22);
    box(1.28, 0.12, 1.28, red, car, 0, 1.19, -0.22);
    for (const x of [-0.88, 0.88]) {
      for (const z of [-1, 1]) {
        const wheel = new THREE.Mesh(
          new THREE.CylinderGeometry(0.34, 0.34, 0.27, 8), black
        );
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(x, 0.34, z);
        car.add(wheel);
      }
      box(0.27, 0.17, 0.07, white, car, x * 0.73, 0.6, 1.59);
    }

    const lapEl = document.querySelector('#lap');
    const bestEl = document.querySelector('#best');
    const statusEl = document.querySelector('#status');
    const storageKey = 'pine-loop-best-v1';
    const format = seconds => `${seconds.toFixed(2)} s`;
    let best = Infinity;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (saved > 0 && Number.isFinite(saved)) best = saved;
    } catch {
      // The game still works if browser storage is unavailable.
    }
    if (Number.isFinite(best)) bestEl.textContent = format(best);

    const keys = new Set();
    const controls = new Set([
      'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyR'
    ]);
    addEventListener('keydown', event => {
      if (!controls.has(event.code)) return;
      event.preventDefault();
      keys.add(event.code);
      if (event.code === 'KeyR' && !event.repeat) reset();
    });
    addEventListener('keyup', event => keys.delete(event.code));
    addEventListener('blur', () => keys.clear());

    let speed, yaw, startedAt, nextGate;
    const follow = new THREE.Vector3();
    const look = new THREE.Vector3();
    function updateCamera(dt, snap = false) {
      const fx = Math.sin(yaw), fz = Math.cos(yaw);
      follow.set(car.position.x - fx * 8.5, 5.1, car.position.z - fz * 8.5);
      look.set(car.position.x + fx * 4.5, 0.8, car.position.z + fz * 4.5);
      camera.position.lerp(follow, snap ? 1 : 1 - Math.exp(-8 * dt));
      camera.lookAt(look);
    }

    function reset() {
      const { point, tangent } = samples[0];
      car.position.copy(point).addScaledVector(tangent, -5);
      yaw = Math.atan2(tangent.x, tangent.z);
      car.rotation.y = yaw;
      speed = 0;
      startedAt = null;
      nextGate = 0;
      lapEl.textContent = '0.00 s';
      statusEl.textContent = 'Cross the start line';
      updateCamera(0, true);
    }

    // Return where the movement segment crosses the gate, or null.
    // Only forward crossings within the painted road count.
    function crossing(index, fromX, fromZ, toX, toZ) {
      const { point, tangent, side } = samples[index];
      const a = (fromX - point.x) * tangent.x + (fromZ - point.z) * tangent.z;
      const b = (toX - point.x) * tangent.x + (toZ - point.z) * tangent.z;
      if (a >= 0 || b < 0) return null;
      const t = -a / (b - a);
      const x = fromX + (toX - fromX) * t;
      const z = fromZ + (toZ - fromZ) * t;
      return Math.abs((x - point.x) * side.x + (z - point.z) * side.z) <= halfRoad
        ? t : null;
    }

    reset();
    let previous = performance.now();

    function frame(now) {
      requestAnimationFrame(frame);
      const frameStart = previous;
      const dt = Math.min((now - previous) / 1000, 0.05);
      previous = now;

      const throttle = Number(keys.has('KeyW') || keys.has('ArrowUp'))
                     - Number(keys.has('KeyS') || keys.has('ArrowDown'));
      const steer = Number(keys.has('KeyA') || keys.has('ArrowLeft'))
                  - Number(keys.has('KeyD') || keys.has('ArrowRight'));
      const { x: oldX, z: oldZ } = car.position;
      const onRoad = roadDistanceSq(oldX, oldZ) <= halfRoad ** 2;

      speed += throttle * 19 * dt;
      speed *= Math.exp(-(onRoad ? (throttle ? 0.42 : 1.35) : 2.1) * dt);
      const cap = onRoad ? 31 : 9;
      speed = THREE.MathUtils.clamp(speed, -Math.min(10, cap), cap);
      yaw += steer * 1.95 * Math.min(Math.abs(speed) / 6, 1) * Math.sign(speed) * dt;
      car.rotation.y = yaw;
      car.position.x = THREE.MathUtils.clamp(oldX + Math.sin(yaw) * speed * dt, -95, 95);
      car.position.z = THREE.MathUtils.clamp(oldZ + Math.cos(yaw) * speed * dt, -80, 80);

      const t = crossing(gateIndices[nextGate], oldX, oldZ, car.position.x, car.position.z);
      if (t !== null) {
        const crossedAt = Math.max(frameStart, now - dt * 1000) + t * dt * 1000;
        if (nextGate === 0) {
          if (startedAt !== null) {
            const lapTime = (crossedAt - startedAt) / 1000;
            const record = lapTime < best;
            if (record) {
              best = lapTime;
              bestEl.textContent = format(best);
              try { localStorage.setItem(storageKey, String(best)); } catch {}
            }
            statusEl.textContent = `${record ? 'New best' : 'Last lap'}: ${format(lapTime)} · 0/3`;
          } else {
            statusEl.textContent = 'Checkpoints: 0/3';
          }
          startedAt = crossedAt;
          nextGate = 1;
        } else {
          statusEl.textContent = nextGate === 3
            ? 'Checkpoints: 3/3 · Head to the finish'
            : `Checkpoints: ${nextGate}/3`;
          nextGate = (nextGate + 1) % gateIndices.length;
        }
      }

      if (startedAt !== null) lapEl.textContent = format((now - startedAt) / 1000);
      updateCamera(dt);
      renderer.render(scene, camera);
    }
    requestAnimationFrame(frame);
  </script>
</body>
</html>
