    canvas { display: block; }
    #hud {
      position: fixed; top: 16px; left: 16px; z-index: 1;
      padding: 14px 18px; border-radius: 10px;
      background: #14212be8; color: #fff;
      font: 14px/1.55 system-ui, sans-serif;
      font-variant-numeric: tabular-nums;
      pointer-events: none;
    }
    h1 { margin: 0 0 6px; font-size: 18px; }
    #status { margin-top: 5px; color: #ffdc86; }
    #controls { margin-top: 8px; color: #d0dce5; font-size: 12px; }
  </style>
</head>
<body>
  <section id="hud" aria-label="Race information">
    <h1>Pine Loop Racer</h1>
    <div>Current: <strong id="current">—</strong></div>
    <div>Last: <strong id="last">—</strong></div>
    <div>Best: <strong id="best">—</strong></div>
    <div id="status">Cross the striped line to start.</div>
    <div id="controls">WASD / arrows · R to restart</div>
  </section>

  <script type="module">
    import * as THREE from
      "https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js";

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xafd9ef);
    scene.fog = new THREE.Fog(0xafd9ef, 95, 220);

    const camera = new THREE.PerspectiveCamera(62, 1, 0.1, 350);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    document.body.appendChild(renderer.domElement);

    function resize() {
      renderer.setSize(innerWidth, innerHeight);
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
    }
    addEventListener("resize", resize);
    resize();

    scene.add(new THREE.HemisphereLight(0xf2faff, 0x596843, 2.1));
    const sun = new THREE.DirectionalLight(0xffe6bf, 2.4);
    sun.position.set(-30, 50, -20);
    scene.add(sun);

    const mat = color => new THREE.MeshStandardMaterial({
      color, roughness: 0.9, flatShading: true
    });

    function mesh(geometry, material, parent, x, y, z) {
      const object = new THREE.Mesh(geometry, material);
      object.position.set(x, y, z);
      parent.add(object);
      return object;
    }

    function box(w, h, d, material, parent, x, y, z) {
      return mesh(new THREE.BoxGeometry(w, h, d), material, parent, x, y, z);
    }

    const grass = mesh(new THREE.PlaneGeometry(500, 500),
      mat(0x77a85a), scene, 0, 0, 0);
    grass.rotation.x = -Math.PI / 2;

    // The road is bounded by two concentric ellipses.
    const A = 42, B = 28, W = 5;
    const TAU = Math.PI * 2;
    const N = 128;

    function ring(inner, outer, y, palette) {
      const vertices = [], colors = [];
      function point(offset, angle) {
        return [(A + offset) * Math.cos(angle), y,
                (B + offset) * Math.sin(angle)];
      }
      for (let i = 0; i < N; i++) {
        const a = i * TAU / N, b = (i + 1) * TAU / N;
        const p = point(inner, a), q = point(inner, b);
        const r = point(outer, a), s = point(outer, b);
        vertices.push(...p, ...q, ...r, ...q, ...s, ...r);
        const c = new THREE.Color(palette[Math.floor(i / 2) % palette.length]);
        for (let j = 0; j < 6; j++) colors.push(c.r, c.g, c.b);
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
      geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
      geometry.computeVertexNormals();
      scene.add(new THREE.Mesh(geometry,
        new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1 })));
    }

    ring(-W, W, 0.025, [0x424851]);
    ring(-W, -W + 0.55, 0.04, [0xeeece1, 0xcd4542]);
    ring(W - 0.55, W, 0.04, [0xeeece1, 0xcd4542]);

    const white = mat(0xffffff), black = mat(0x15171c);
    for (let i = 0; i < 10; i++) {
      for (let j = 0; j < 2; j++) {
        box(1, 0.02, 0.55, (i + j) % 2 ? white : black,
          scene, A - W + i + 0.5, 0.055, (j - 0.5) * 0.55);
      }
    }

    const bark = mat(0x805638), pine = mat(0x286748);
    const trunk = new THREE.CylinderGeometry(0.24, 0.36, 1.65, 5);
    const crown = new THREE.ConeGeometry(1.65, 3.8, 5);
    let seed = 731;
    function random() {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed / 4294967296;
    }

    // Keep scenery clear of the driving surface.
    for (let i = 0; i < 125; i++) {
      const x = (random() - 0.5) * 170;
      const z = (random() - 0.5) * 140;
      if (Math.hypot(x / (A + 10), z / (B + 10)) < 1 &&
          Math.hypot(x / (A - 12), z / (B - 12)) > 1) continue;
      const scale = 0.65 + random() * 0.75;
      const tree = new THREE.Group();
      tree.position.set(x, 0, z);
      tree.scale.setScalar(scale);
      tree.rotation.y = random() * TAU;
      scene.add(tree);
      mesh(trunk, bark, tree, 0, 0.825, 0);
      mesh(crown, pine, tree, 0, 2.6, 0);
    }

    // Local +Z is the car's forward direction.
    const car = new THREE.Group();
    scene.add(car);
    const red = mat(0xef483b), glass = mat(0x243c56);
    box(1.85, 0.55, 3.25, red, car, 0, 0.59, 0);
    box(1.35, 0.48, 1.45, glass, car, 0, 1.04, -0.25);
    box(1.4, 0.12, 0.75, red, car, 0, 1.3, -0.32);
    const tire = new THREE.CylinderGeometry(0.37, 0.37, 0.34, 10);
    tire.rotateZ(Math.PI / 2);
    for (const side of [-1, 1]) {
      for (const end of [-1, 1]) {
        mesh(tire, black, car, side * 0.93, 0.39, end * 1.05);
      }
      box(0.38, 0.18, 0.05, white, car, side * 0.59, 0.64, 1.65);
    }

    const keys = new Set();
    const drivingKeys = new Set([
      "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight",
      "KeyW", "KeyA", "KeyS", "KeyD"
    ]);
    addEventListener("keydown", event => {
      if (drivingKeys.has(event.code)) {
        event.preventDefault();
        keys.add(event.code);
      }
      if (event.code === "KeyR" && !event.repeat) reset();
    });
    addEventListener("keyup", event => keys.delete(event.code));
    addEventListener("blur", () => keys.clear());
    const down = (...codes) => codes.some(code => keys.has(code));

    const currentEl = document.querySelector("#current");
    const lastEl = document.querySelector("#last");
    const bestEl = document.querySelector("#best");
    const statusEl = document.querySelector("#status");
    const storageKey = "pine-loop-best-ms-v1";

    let best = null;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch { /* The game still works if browser storage is blocked. */ }

    function format(ms) {
      if (ms === null) return "—";
      const total = Math.floor(ms / 10);
      const minutes = Math.floor(total / 6000);
      const seconds = String(Math.floor(total / 100) % 60).padStart(2, "0");
      return `${minutes}:${seconds}.${String(total % 100).padStart(2, "0")}`;
    }
    bestEl.textContent = format(best);

    let x, z, yaw, speed, lapStart, last, nextGate;
    const cameraTarget = new THREE.Vector3();
    const lookTarget = new THREE.Vector3();

    function followCamera(blend) {
      const fx = Math.sin(yaw), fz = Math.cos(yaw);
      cameraTarget.set(x - fx * 9, 6, z - fz * 9);
      camera.position.lerp(cameraTarget, blend);
      lookTarget.set(x + fx * 5, 0.8, z + fz * 5);
      camera.lookAt(lookTarget);
    }

    function reset() {
      x = A; z = -5; yaw = 0; speed = 0;
      lapStart = null; last = null; nextGate = 0;
      car.position.set(x, 0, z);
      car.rotation.y = yaw;
      followCamera(1);
      currentEl.textContent = lastEl.textContent = "—";
      statusEl.textContent = "Cross the striped line to start.";
    }

    // In order: start, far end, opposite side, near end, finish.
    // A gate only counts inside the road and in the forward direction.
    const gates = [
      { axis: "z", direction: 1, center: A },
      { axis: "x", direction: -1, center: B },
      { axis: "z", direction: -1, center: -A },
      { axis: "x", direction: 1, center: -B }
    ];

    function crossed(gate, oldX, oldZ) {
      const isZ = gate.axis === "z";
      const before = isZ ? oldZ : oldX;
      const after = isZ ? z : x;
      if (before * gate.direction >= 0 || after * gate.direction < 0) return null;
      const t = -before / (after - before);
      const other = isZ ? oldX + (x - oldX) * t : oldZ + (z - oldZ) * t;
      return Math.abs(other - gate.center) <= W ? t : null;
    }

    function checkLap(oldX, oldZ, frameStart, now) {
      const t = crossed(gates[nextGate], oldX, oldZ);
      if (t === null) return;
      if (nextGate === 0) {
        const crossingTime = frameStart + (now - frameStart) * t;
        if (lapStart !== null) {
          last = crossingTime - lapStart;
          lastEl.textContent = format(last);
          if (best === null || last < best) {
            best = last;
            bestEl.textContent = format(best);
            try { localStorage.setItem(storageKey, String(best)); } catch {}
          }
        }
        lapStart = crossingTime;
      }
      nextGate = (nextGate + 1) % gates.length;
      statusEl.textContent = nextGate === 0
        ? "3/3 checkpoints · head for the finish"
        : `${nextGate - 1}/3 checkpoints`;
    }

    function onRoad() {
      return Math.hypot(x / (A + W), z / (B + W)) <= 1 &&
             Math.hypot(x / (A - W), z / (B - W)) >= 1;
    }

    reset();
    let previous = performance.now();

    function frame(now) {
      const frameStart = previous;
      const dt = Math.min(Math.max((now - previous) / 1000, 0), 0.05);
      previous = now;
      const oldX = x, oldZ = z;
      const road = onRoad();
      const throttle = Number(down("KeyW", "ArrowUp")) -
                       Number(down("KeyS", "ArrowDown"));
      const steering = Number(down("KeyA", "ArrowLeft")) -
                       Number(down("KeyD", "ArrowRight"));

      if (throttle) {
        const braking = speed * throttle < 0;
        speed += throttle * (braking ? 34 : 15) * dt;
      } else {
        speed *= Math.exp(-1.45 * dt);
      }

      const limit = road ? 30 : 11;
      if (Math.abs(speed) > limit) {
        speed = Math.sign(speed) *
          (limit + (Math.abs(speed) - limit) * Math.exp(-5 * dt));
      }
      speed = THREE.MathUtils.clamp(speed, -9, 30);

      const grip = Math.min(Math.abs(speed) / 6, 1);
      yaw += steering * Math.sign(speed) * grip * (road ? 1.7 : 1.4) * dt;
      x = THREE.MathUtils.clamp(x + Math.sin(yaw) * speed * dt, -105, 105);
      z = THREE.MathUtils.clamp(z + Math.cos(yaw) * speed * dt, -90, 90);

      car.position.set(x, 0, z);
      car.rotation.y = yaw;
      checkLap(oldX, oldZ, frameStart, now);
      currentEl.textContent = format(lapStart === null ? null : now - lapStart);
      followCamera(1 - Math.exp(-8 * dt));
      renderer.render(scene, camera);
      requestAnimationFrame(frame);
    }

    requestAnimationFrame(frame);
  </script>
</body>
</html>
```

### Run and verify

From the folder containing `index.html`, run `python -m http.server 8000` and open `http://localhost:8000/`. The browser needs internet access to load Three.js from the CDN.

I haven’t run the game here. I’d verify it in the browser with these checks:

1. **Load and controls:** Check that the scene renders without console errors. Test both key sets, braking into reverse, and steering. Drive onto the grass and confirm the car slows down.
2. **Lap timing:** Accelerate across the striped line, then follow the track by turning left around the oval. Check that the timer starts at the line, the checkpoint counter reaches `3/3`, and the next line crossing records a lap and starts a new timer.
3. **Invalid laps:** Cross the line backward or turn around and recross before visiting all three checkpoints. Neither should record a lap.
4. **Best lap and reset:** Complete two laps at different speeds. Confirm that **Best** shows the faster lap, that **R** resets the car and current run without clearing **Best**, and that reloading preserves **Best** when browser storage is available.

Save this as `index.html`. It’s a complete low-poly racer with one closed track, a chase camera, keyboard controls, and a best lap saved in your browser. The only external dependency is Three.js, loaded from a CDN.

```html
<!doctype html>
