<body>
  <section id="hud" aria-label="Race information">
    <h1>Switchback Sprint</h1>
    <div class="row"><span>Lap</span><span class="value" id="lap">1</span></div>
    <div class="row"><span>Current</span><span class="value" id="current">0:00.000</span></div>
    <div class="row"><span>Best</span><span class="value" id="best">—</span></div>
    <div id="message">Cross the line to start</div>
  </section>
  <div id="help">W / ↑ accelerate · S / ↓ brake or reverse · A D / ← → steer · R restart</div>

  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xa8d9ed);
    scene.fog = new THREE.Fog(0xa8d9ed, 105, 230);

    const camera = new THREE.PerspectiveCamera(58, innerWidth / innerHeight, 0.1, 350);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    document.body.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xfff6dc, 0x547855, 2.3));
    const sun = new THREE.DirectionalLight(0xffe4bb, 2.1);
    sun.position.set(-35, 55, 25);
    scene.add(sun);

    const material = color => new THREE.MeshStandardMaterial({ color, flatShading: true });
    function mesh(geometry, mat, parent, x = 0, y = 0, z = 0) {
      const obj = new THREE.Mesh(geometry, mat);
      obj.position.set(x, y, z);
      parent.add(obj);
      return obj;
    }

    const grass = mesh(new THREE.PlaneGeometry(420, 420), material(0x6aa353), scene);
    grass.rotation.x = -Math.PI / 2;

    const route = [
      [0, -38], [35, -39], [56, -19], [48, 8],
      [64, 32], [38, 52], [-3, 47], [-31, 31],
      [-58, 19], [-58, -11], [-37, -35]
    ];
    const track = new THREE.CatmullRomCurve3(
      route.map(([x, z]) => new THREE.Vector3(x, 0, z)), true
    );
    const N = 360;
    const halfWidth = 5.3;
    const samples = track.getSpacedPoints(N);
    samples.pop();

    const tangents = samples.map((_, i) =>
      samples[(i + 1) % N].clone()
        .sub(samples[(i + N - 1) % N]).normalize()
    );
    const sides = tangents.map(t => new THREE.Vector3(t.z, 0, -t.x));

    function ribbon(left, right, y, colors, include = () => true) {
      const positions = [], vertexColors = [];
      const palette = colors.map(c => new THREE.Color(c));
      function vertex(i, offset, color) {
        const p = samples[i], s = sides[i];
        positions.push(p.x + s.x * offset, y, p.z + s.z * offset);
        vertexColors.push(color.r, color.g, color.b);
      }
      for (let i = 0; i < N; i++) {
        if (!include(i)) continue;
        const j = (i + 1) % N;
        const color = palette[Math.floor(i / 4) % palette.length];
        vertex(i, left, color); vertex(j, left, color); vertex(i, right, color);
        vertex(i, right, color); vertex(j, left, color); vertex(j, right, color);
      }
      const geometry = new THREE.BufferGeometry();
      geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      geometry.setAttribute('color', new THREE.Float32BufferAttribute(vertexColors, 3));
      geometry.computeVertexNormals();
      mesh(geometry, new THREE.MeshStandardMaterial({ vertexColors: true }), scene);
    }

    ribbon(-halfWidth, halfWidth, 0.035, [0x343a43]);
    ribbon(-halfWidth - 0.45, -halfWidth, 0.045, [0xe55748, 0xffe9c9]);
    ribbon(halfWidth, halfWidth + 0.45, 0.045, [0xe55748, 0xffe9c9]);
    ribbon(-0.055, 0.055, 0.046, [0xa0a6aa], i => i % 8 < 3 && i > 2 && i < N - 3);

    const start = new THREE.Group();
    start.position.copy(samples[0]);
    start.rotation.y = Math.atan2(tangents[0].x, tangents[0].z);
    scene.add(start);
    const white = material(0xfff6df), black = material(0x202530);
    const tile = new THREE.BoxGeometry(2 * halfWidth / 12, 0.026, 0.48);
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 12; col++) {
        mesh(tile, (row + col) % 2 ? white : black, start,
          -halfWidth + (col + 0.5) * 2 * halfWidth / 12, 0.052, (row - 0.5) * 0.48);
      }
    }

    // Reused geometry and a seeded random generator keep scenery lightweight.
    const trunk = new THREE.CylinderGeometry(0.16, 0.25, 1.5, 5);
    const leaves = new THREE.ConeGeometry(1.35, 3.2, 5);
    const wood = material(0x795135);
    const greens = [0x286353, 0x377b4b, 0x526f31].map(material);
    let seed = 77;
    function random() {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      return seed / 4294967296;
    }
    for (let i = 0; i < 150; i++) {
      const x = (random() - 0.5) * 180, z = (random() - 0.5) * 150;
      if (samples.some(p => (p.x - x) ** 2 + (p.z - z) ** 2 < 10 ** 2)) continue;
      const tree = new THREE.Group();
      tree.position.set(x, 0, z);
      tree.scale.setScalar(0.7 + random() * 0.8);
      tree.rotation.y = random() * Math.PI;
      scene.add(tree);
      mesh(trunk, wood, tree, 0, 0.75, 0);
      mesh(leaves, greens[i % greens.length], tree, 0, 2.4, 0);
    }

    const car = new THREE.Group();
    scene.add(car);
    const red = material(0xf13e38), glass = material(0x253e52);
    mesh(new THREE.BoxGeometry(1.75, 0.48, 3.2), red, car, 0, 0.56, 0);
    mesh(new THREE.BoxGeometry(1.35, 0.47, 1.45), glass, car, 0, 1.0, -0.21);
    mesh(new THREE.BoxGeometry(1.64, 0.13, 0.38), red, car, 0, 0.94, -1.39);
    const wheel = new THREE.CylinderGeometry(0.36, 0.36, 0.29, 10);
    const lamp = new THREE.BoxGeometry(0.33, 0.14, 0.06);
    for (const x of [-0.85, 0.85]) {
      for (const z of [-1.02, 1.02]) {
        mesh(wheel, black, car, x, 0.38, z).rotation.z = Math.PI / 2;
      }
      mesh(lamp, white, car, x * 0.72, 0.61, 1.61);
    }

    const ui = Object.fromEntries(
      ['lap', 'current', 'best', 'message'].map(id => [id, document.getElementById(id)])
    );
    const recordKey = 'switchback-sprint-best-v1';
    let best = null;
    try {
      const saved = Number(localStorage.getItem(recordKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch { /* Storage may be unavailable; keep the record in memory. */ }

    function format(seconds) {
      const ms = Math.floor(seconds * 1000);
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60).padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
    }

    const keys = new Set();
    const controls = new Set(['KeyW', 'KeyA', 'KeyS', 'KeyD',
      'ArrowUp', 'ArrowLeft', 'ArrowDown', 'ArrowRight', 'KeyR']);
    addEventListener('keydown', e => {
      if (!controls.has(e.code)) return;
      e.preventDefault();
      keys.add(e.code);
      if (e.code === 'KeyR' && !e.repeat) restart();
    });
    addEventListener('keyup', e => keys.delete(e.code));
    addEventListener('blur', () => keys.clear());
    document.addEventListener('visibilitychange', () => keys.clear());

    function nearest(p) {
      let index = 0, distance2 = Infinity;
      for (let i = 0; i < N; i++) {
        const q = samples[i];
        const d = (p.x - q.x) ** 2 + (p.z - q.z) ** 2;
        if (d < distance2) { index = i; distance2 = d; }
      }
      return { index, distance2 };
    }

    const forward = new THREE.Vector3(), cameraGoal = new THREE.Vector3();
    const aim = new THREE.Vector3(), previousPosition = new THREE.Vector3();
    let yaw, speed, lap, elapsed, racing, nextGate;
    const gates = [N / 4, N / 2, 3 * N / 4];
    const held = (a, b) => keys.has(a) || keys.has(b);

    // Return the fraction of the frame at which the car crosses a gate
    // forward, or null if it misses the gate or crosses in reverse.
    function crossing(index) {
      const center = samples[index], t = tangents[index], s = sides[index];
      const ax = previousPosition.x - center.x, az = previousPosition.z - center.z;
      const bx = car.position.x - center.x, bz = car.position.z - center.z;
      const a = ax * t.x + az * t.z, b = bx * t.x + bz * t.z;
      if (a >= 0 || b < 0) return null;
      const f = -a / (b - a);
      const lateral = (ax + (bx - ax) * f) * s.x + (az + (bz - az) * f) * s.z;
      return Math.abs(lateral) <= halfWidth ? f : null;
    }

    function updateCamera(blend) {
      forward.set(Math.sin(yaw), 0, Math.cos(yaw));
      cameraGoal.copy(car.position).addScaledVector(forward, -8.5);
      cameraGoal.y += 5.2;
      camera.position.lerp(cameraGoal, blend);
      aim.copy(car.position).addScaledVector(forward, 4);
      aim.y += 0.9;
      camera.lookAt(aim);
    }

    function restart() {
      const spawn = N - 9;
      car.position.copy(samples[spawn]);
      yaw = Math.atan2(tangents[spawn].x, tangents[spawn].z);
      car.rotation.y = yaw;
      speed = elapsed = nextGate = 0;
      lap = 1;
      racing = false;
      ui.message.textContent = 'Cross the line to start';
      updateCamera(1);
    }

    function drive(dt) {
      previousPosition.copy(car.position);
      const { distance2 } = nearest(car.position);
      const onRoad = distance2 <= (halfWidth + 0.45) ** 2;
      const accelerate = held('KeyW', 'ArrowUp');
      const brake = held('KeyS', 'ArrowDown');
      const steer = Number(held('KeyA', 'ArrowLeft')) - Number(held('KeyD', 'ArrowRight'));

      if (accelerate) speed += (speed < 0 ? 24 : 14) * dt;
      if (brake) speed -= (speed > 0 ? 26 : 9) * dt;
      speed *= Math.exp(-(onRoad ? 0.42 : 2.2) * dt);
      speed = THREE.MathUtils.clamp(speed, -7, 26);
      yaw += steer * 1.75 * Math.min(Math.abs(speed) / 5, 1) * Math.sign(speed) * dt;
      car.rotation.y = yaw;
      car.position.x += Math.sin(yaw) * speed * dt;
      car.position.z += Math.cos(yaw) * speed * dt;

      if (racing && nextGate < gates.length && crossing(gates[nextGate]) !== null) {
        nextGate++;
        ui.message.textContent = `Checkpoints: ${nextGate}/${gates.length}`;
      }

      const finish = crossing(0);
      if (finish !== null && (!racing || nextGate === gates.length)) {
        if (racing) {
          const result = elapsed + finish * dt;
          const record = best === null || result < best;
          if (record) {
            best = result;
            try { localStorage.setItem(recordKey, String(best)); } catch {}
          }
          ui.message.textContent = `${record ? 'New best' : 'Last lap'}: ${format(result)}`;
          lap++;
        } else {
          ui.message.textContent = 'Checkpoints: 0/3';
        }
        racing = true;
        elapsed = (1 - finish) * dt;
        nextGate = 0;
      } else if (racing) {
        elapsed += dt;
      }
    }

    addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });

    restart();
    let last = performance.now();
    document.addEventListener('visibilitychange', () => { last = performance.now(); });
    renderer.setAnimationLoop(now => {
      const dt = THREE.MathUtils.clamp((now - last) / 1000, 0, 0.1);
      last = now;
      if (!document.hidden) {
        // Substeps keep steering and gate crossings stable on slower frames.
        const steps = Math.max(1, Math.ceil(dt / (1 / 120)));
        for (let i = 0; i < steps; i++) drive(dt / steps);
        updateCamera(1 - Math.exp(-7 * dt));
        ui.lap.textContent = lap;
        ui.current.textContent = format(elapsed);
        ui.best.textContent = best === null ? '—' : format(best);
        renderer.render(scene, camera);
      }
    });
  </script>
</body>
</html>
```

