      pointer-events: none; }
  </style>
</head>
<body>
  <section id="hud" aria-label="Race information">
    <h1>Pine Ridge Racer</h1>
    <div class="row"><span>Current lap</span><output id="lap">0:00.000</output></div>
    <div class="row"><span>Best lap</span><output id="best">—</output></div>
    <div class="row"><span>Speed</span><output id="speed">0 km/h</output></div>
    <div id="status" role="status">Accelerate to start</div>
  </section>
  <p id="controls">WASD / arrows to drive · R to reset</p>

  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xb9ddeb);
    scene.fog = new THREE.Fog(0xb9ddeb, 95, 220);
    const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.1, 300);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    renderer.setSize(innerWidth, innerHeight);
    document.body.prepend(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xfff8df, 0x617c52, 2.1));
    const sun = new THREE.DirectionalLight(0xffefd0, 2.2);
    sun.position.set(-30, 50, 15);
    scene.add(sun);

    const mat = color => new THREE.MeshStandardMaterial({ color, flatShading: true });
    function mesh(geometry, material, x, y, z, parent = scene) {
      const object = new THREE.Mesh(geometry, material);
      object.position.set(x, y, z);
      parent.add(object);
      return object;
    }
    const ground = mesh(new THREE.PlaneGeometry(600, 600), mat(0x609451), 0, -0.03, 0);
    ground.rotation.x = -Math.PI / 2;

    // Sample a closed centerline, then build strips offset from it.
    const points = [
      [0, -31], [27, -32], [47, -19], [48, 3], [33, 23],
      [9, 30], [-12, 21], [-36, 28], [-51, 10], [-46, -14], [-25, -29]
    ];
    const curve = new THREE.CatmullRomCurve3(
      points.map(([x, z]) => new THREE.Vector3(x, 0, z)), true
    );
    const N = 240, HALF = 5.3;
    const samples = Array.from({ length: N }, (_, i) => {
      const t = i / N;
      const p = curve.getPointAt(t);
      const f = curve.getTangentAt(t).normalize();
      return { p, f, right: new THREE.Vector3(f.z, 0, -f.x) };
    });

    function strip(vertices, a, b, left, right, y) {
      const corner = (s, offset) => [
        s.p.x + s.right.x * offset, y, s.p.z + s.right.z * offset
      ];
      const al = corner(a, left), ar = corner(a, right);
      const bl = corner(b, left), br = corner(b, right);
      vertices.push(...al, ...bl, ...ar, ...ar, ...bl, ...br);
    }
    function surface(vertices, color) {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
      g.computeVertexNormals();
      mesh(g, mat(color), 0, 0, 0);
    }
    const asphalt = [], white = [], red = [], dashes = [], checks = [];
    for (let i = 0; i < N; i++) {
      const a = samples[i], b = samples[(i + 1) % N];
      strip(asphalt, a, b, -HALF, HALF, 0.01);
      const curb = Math.floor(i / 3) % 2 ? red : white;
      strip(curb, a, b, -HALF - 0.36, -HALF, 0.02);
      strip(curb, a, b, HALF, HALF + 0.36, 0.02);
      if (i % 8 < 3 && i > 2 && i < N - 2) {
        strip(dashes, a, b, -0.065, 0.065, 0.023);
      }
    }
    for (let row = 0; row < 2; row++) {
      const a = samples[(N - 1 + row) % N], b = samples[row];
      for (let j = 0; j < 12; j++) {
        const left = -HALF + j * 2 * HALF / 12;
        strip((row + j) % 2 ? white : checks, a, b, left, left + 2 * HALF / 12, 0.026);
      }
    }
    surface(asphalt, 0x454b55);
    surface(white, 0xf5f3e8);
    surface(red, 0xd64542);
    surface(dashes, 0xe5bf62);
    surface(checks, 0x1b2028);

    // Distance to the centerline segments, not just the sampled points.
    function roadDistance(x, z) {
      let best = Infinity;
      for (let i = 0; i < N; i++) {
        const a = samples[i].p, b = samples[(i + 1) % N].p;
        const dx = b.x - a.x, dz = b.z - a.z;
        const t = THREE.MathUtils.clamp(
          ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz), 0, 1
        );
        best = Math.min(best, (x - a.x - t * dx) ** 2 + (z - a.z - t * dz) ** 2);
      }
      return Math.sqrt(best);
    }

    const trunk = new THREE.CylinderGeometry(0.14, 0.22, 1.5, 5);
    const foliage = new THREE.ConeGeometry(1.35, 3.4, 6);
    const bark = mat(0x795234);
    const greens = [mat(0x2e6944), mat(0x397e4d), mat(0x4b8953)];
    let seed = 29;
    function random() {
      seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
      return seed / 4294967296;
    }
    for (let i = 0; i < 190; i++) {
      const x = (random() - 0.5) * 175, z = (random() - 0.5) * 145;
      if (roadDistance(x, z) < HALF + 6) continue;
      const tree = new THREE.Group();
      tree.position.set(x, 0, z);
      tree.scale.setScalar(0.65 + random() * 0.8);
      tree.rotation.y = random() * Math.PI;
      scene.add(tree);
      mesh(trunk, bark, 0, 0.75, 0, tree);
      mesh(foliage, greens[i % greens.length], 0, 2.45, 0, tree);
    }

    const car = new THREE.Group();
    scene.add(car);
    const paint = mat(0xff673b), glass = mat(0x29475c), rubber = mat(0x20242a);
    const box = (w, h, l, m, x, y, z) =>
      mesh(new THREE.BoxGeometry(w, h, l), m, x, y, z, car);
    box(1.8, 0.42, 3.35, paint, 0, 0.52, 0);
    box(1.38, 0.45, 1.45, glass, 0, 0.92, -0.23);
    box(1.42, 0.12, 1.48, paint, 0, 1.17, -0.23);
    const lamps = mat(0xffedb5);
    for (const x of [-0.63, 0.63]) box(0.32, 0.19, 0.07, lamps, x, 0.56, 1.69);
    for (const x of [-0.88, 0.88]) {
      for (const z of [-1.04, 1.04]) {
        const wheel = mesh(new THREE.CylinderGeometry(0.34, 0.34, 0.32, 10),
          rubber, x, 0.34, z, car);
        wheel.rotation.z = Math.PI / 2;
      }
    }
    const shadow = mesh(new THREE.CircleGeometry(1, 20),
      new THREE.MeshBasicMaterial({ color: 0x142018, transparent: true, opacity: 0.28 }),
      0, 0.032, 0, car);
    shadow.rotation.x = -Math.PI / 2;
    shadow.scale.set(1.26, 1.92, 1);

    const lapEl = document.querySelector('#lap');
    const bestEl = document.querySelector('#best');
    const speedEl = document.querySelector('#speed');
    const status = document.querySelector('#status');
    const storageKey = 'pine-ridge-best-v1';
    let best = 0;
    try {
      const saved = Number(localStorage.getItem(storageKey));
      if (Number.isFinite(saved) && saved > 0) best = saved;
    } catch {} // Still playable if storage is unavailable.

    function format(seconds) {
      const ms = Math.floor(seconds * 1000);
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60)
        .padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
    }
    bestEl.textContent = best ? format(best) : '—';

    // Gates are perpendicular to the centerline. A crossing counts only
    // in the forward direction, within road width, and in sequence.
    const gates = [N / 4, N / 2, 3 * N / 4, 0].map(i => samples[i]);
    const keys = new Set();
    const driveKeys = new Set([
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'
    ]);
    addEventListener('keydown', e => {
      if (driveKeys.has(e.code)) {
        e.preventDefault();
        keys.add(e.code);
      }
      if (e.code === 'KeyR' && !e.repeat) reset('Reset · accelerate to start');
    });
    addEventListener('keyup', e => keys.delete(e.code));
    addEventListener('blur', () => keys.clear());
    document.addEventListener('visibilitychange', () => {
      keys.clear();
      if (document.hidden && started) reset('Tab switched · lap reset');
    });

    let yaw, velocity, elapsed, started, nextGate;
    const forward = new THREE.Vector3(), cameraGoal = new THREE.Vector3();
    const look = new THREE.Vector3(), previous = new THREE.Vector3();
    function follow(dt, snap = false) {
      forward.set(Math.sin(yaw), 0, Math.cos(yaw));
      cameraGoal.copy(car.position).addScaledVector(forward, -8.5);
      cameraGoal.y += 5.2;
      camera.position.lerp(cameraGoal, snap ? 1 : 1 - Math.exp(-7 * dt));
      look.copy(car.position).addScaledVector(forward, 4.5);
      look.y += 0.8;
      camera.lookAt(look);
    }
    function reset(message = 'Accelerate to start') {
      const start = samples[2];
      car.position.copy(start.p);
      yaw = Math.atan2(start.f.x, start.f.z);
      car.rotation.y = yaw;
      velocity = elapsed = nextGate = 0;
      started = false;
      status.textContent = message;
      follow(0, true);
    }

    function crossed(gate, from, to) {
      const along = p => (p.x - gate.p.x) * gate.f.x + (p.z - gate.p.z) * gate.f.z;
      const a = along(from), b = along(to);
      if (a >= 0 || b < 0) return false;
      const t = -a / (b - a);
      const x = from.x + (to.x - from.x) * t - gate.p.x;
      const z = from.z + (to.z - from.z) * t - gate.p.z;
      return Math.abs(x * gate.right.x + z * gate.right.z) <= HALF;
    }

    function update(dt, wallTime) {
      const throttle = Number(keys.has('KeyW') || keys.has('ArrowUp')) -
        Number(keys.has('KeyS') || keys.has('ArrowDown'));
      const steer = Number(keys.has('KeyD') || keys.has('ArrowRight')) -
        Number(keys.has('KeyA') || keys.has('ArrowLeft'));
      const distance = roadDistance(car.position.x, car.position.z);
      const grass = distance > HALF + 0.36;
      if (throttle) {
        const braking = velocity * throttle < 0;
        velocity += throttle * (braking ? 32 : throttle > 0 ? 16 : 10) * dt;
      }
      velocity *= Math.exp(-(grass ? 2.4 : throttle ? 0.35 : 0.95) * dt);
      velocity = THREE.MathUtils.clamp(velocity, -8, 32);
      if (Math.abs(velocity) < 0.015) velocity = 0;
      yaw += steer * Math.sign(velocity) * Math.min(Math.abs(velocity) / 5, 1)
        * (1.95 - 0.027 * Math.abs(velocity)) * dt;
      car.rotation.y = yaw;
      previous.copy(car.position);
      car.position.x += Math.sin(yaw) * velocity * dt;
      car.position.z += Math.cos(yaw) * velocity * dt;

      if (distance > HALF + 8) {
        reset('Off course · try again');
        return;
      }
      if (!started && velocity !== 0) {
        started = true;
        status.textContent = 'Checkpoints: 0 / 3';
      }
      if (started) {
        elapsed += wallTime;
        if (crossed(gates[nextGate], previous, car.position)) {
          nextGate++;
          if (nextGate === gates.length) {
            const isBest = !best || elapsed < best;
            if (isBest) {
              best = elapsed;
              bestEl.textContent = format(best);
              try { localStorage.setItem(storageKey, String(best)); } catch {}
            }
            status.textContent = `${isBest ? 'New best' : 'Lap complete'}: ${format(elapsed)}`;
            elapsed = 0;
            nextGate = 0;
          } else {
            status.textContent = `Checkpoints: ${nextGate} / 3`;
          }
        }
      }
      follow(dt);
    }

    reset();
    let last;
    renderer.setAnimationLoop(now => {
      const wallTime = last === undefined ? 0 : (now - last) / 1000;
      last = now;
      // Cap the physics step after a stall, but keep the lap clock on real time.
      if (!document.hidden) update(Math.min(wallTime, 0.05), wallTime);
      lapEl.textContent = format(elapsed);
      speedEl.textContent = `${Math.round(Math.abs(velocity) * 3.6)} km/h`;
      renderer.render(scene, camera);
    });
    addEventListener('resize', () => {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    });
  </script>
</body>
</html>
