  </section>
  <div id="controls">
    <kbd>WASD</kbd> / <kbd>↑ ↓ ← →</kbd> Drive
    &nbsp;·&nbsp; <kbd>Space</kbd> Brake
    &nbsp;·&nbsp; <kbd>R</kbd> Restart run
  </div>

  <script type="module">
    const $ = id => document.getElementById(id);

    try {
      const THREE = await import(
        'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js'
      );
      startGame(THREE);
    } catch (error) {
      $('status').textContent = 'Could not start. Check your connection and WebGL support.';
      console.error(error);
    }

    function startGame(T) {
      const scene = new T.Scene();
      scene.background = new T.Color(0xb7dcef);
      scene.fog = new T.Fog(0xb7dcef, 90, 210);

      const camera = new T.PerspectiveCamera(62, 1, 0.1, 300);
      const renderer = new T.WebGLRenderer({ antialias: true });
      renderer.domElement.setAttribute('aria-label', '3D view of Meadow Circuit');
      document.body.appendChild(renderer.domElement);

      function resize() {
        renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
        renderer.setSize(innerWidth, innerHeight);
        camera.aspect = innerWidth / innerHeight;
        camera.updateProjectionMatrix();
      }
      addEventListener('resize', resize);
      resize();

      scene.add(new T.HemisphereLight(0xebf8ff, 0x58643b, 2.1));
      const sun = new T.DirectionalLight(0xffedc8, 2.5);
      sun.position.set(-20, 50, -30);
      scene.add(sun);

      const material = color => new T.MeshStandardMaterial({
        color, flatShading: true
      });

      function mesh(geometry, mat, parent, x, y, z) {
        const object = new T.Mesh(geometry, mat);
        object.position.set(x, y, z);
        parent.add(object);
        return object;
      }

      const grass = mesh(new T.PlaneGeometry(600, 600), material(0x649759),
                         scene, 0, -0.04, 0);
      grass.rotation.x = -Math.PI / 2;

      // Closed centerline. getPointAt samples it at roughly equal distances.
      const curve = new T.CatmullRomCurve3([
        [-31, -23], [0, -29], [35, -21], [44, 0],
        [28, 23], [4, 21], [-20, 32], [-42, 17], [-46, -5]
      ].map(([x, z]) => new T.Vector3(x, 0, z)), true);
      curve.arcLengthDivisions = 1500;

      const N = 320;
      const HALF = 4.8;
      const points = [], tangents = [], sides = [];
      for (let i = 0; i < N; i++) {
        const at = i / N;
        const tangent = curve.getTangentAt(at);
        points.push(curve.getPointAt(at));
        tangents.push(tangent);
        sides.push(new T.Vector3(tangent.z, 0, -tangent.x));
      }

      function strip(inner, outer, height, colorAt) {
        const positions = [], colors = [];
        const color = new T.Color();
        function vertex(i, offset) {
          const p = points[i % N], s = sides[i % N];
          positions.push(p.x + s.x * offset, height, p.z + s.z * offset);
          colors.push(color.r, color.g, color.b);
        }
        for (let i = 0; i < N; i++) {
          const paint = colorAt(i);
          if (paint === null) continue;
          color.setHex(paint);
          vertex(i, inner);
          vertex(i + 1, inner);
          vertex(i, outer);
          vertex(i, outer);
          vertex(i + 1, inner);
          vertex(i + 1, outer);
        }
        const geometry = new T.BufferGeometry();
        geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
        geometry.setAttribute('color', new T.Float32BufferAttribute(colors, 3));
        geometry.computeVertexNormals();
        scene.add(new T.Mesh(geometry, new T.MeshStandardMaterial({
          vertexColors: true, side: T.DoubleSide, flatShading: true
        })));
      }

      strip(-HALF, HALF, 0, () => 0x383f48);
      const curb = i => Math.floor(i / 4) % 2 ? 0xf5ece0 : 0xdd4c43;
      strip(-HALF - 0.55, -HALF, 0.012, curb);
      strip(HALF, HALF + 0.55, 0.012, curb);
      strip(-0.065, 0.065, 0.014, i => i % 12 < 5 ? 0xb7b5a6 : null);

      // Start/finish checkerboard, oriented across the road.
      const start = points[0];
      const startYaw = Math.atan2(tangents[0].x, tangents[0].z);
      const line = new T.Group();
      line.position.copy(start);
      line.rotation.y = startYaw;
      scene.add(line);
      const tileWidth = HALF * 2 / 16;
      const tile = new T.BoxGeometry(tileWidth, 0.018, 0.32);
      const checker = [material(0xf7f4e9), material(0x161b21)];
      for (let row = 0; row < 2; row++) {
        for (let col = 0; col < 16; col++) {
          mesh(tile, checker[(row + col) % 2], line,
               -HALF + (col + 0.5) * tileWidth, 0.022, (row - 0.5) * 0.32);
        }
      }

      // Returns the closest point on the sampled centerline, not just
      // the closest sample. Used for grass slowdown and lap validation.
      function trackPosition(x, z) {
        let bestDistance = Infinity, progress = 0;
        for (let i = 0; i < N; i++) {
          const a = points[i], b = points[(i + 1) % N];
          const dx = b.x - a.x, dz = b.z - a.z;
          const t = T.MathUtils.clamp(
            ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz), 0, 1
          );
          const ex = x - (a.x + t * dx), ez = z - (a.z + t * dz);
          const d = ex * ex + ez * ez;
          if (d < bestDistance) {
            bestDistance = d;
            progress = ((i + t) % N) / N;
          }
        }
        return { distance: Math.sqrt(bestDistance), progress };
      }

      // Seeded scenery so the landscape stays the same on reload.
      let seed = 7341;
      function random() {
        seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
        return seed / 4294967296;
      }

      const trunk = new T.CylinderGeometry(0.15, 0.23, 1.4, 5);
      const crown = new T.ConeGeometry(1.3, 2.8, 6);
      const bark = material(0x75503a);
      const leaves = [material(0x245f45), material(0x347852), material(0x466f3f)];
      for (let i = 0; i < 145; i++) {
        const x = (random() - 0.5) * 184;
        const z = (random() - 0.5) * 148;
        if (trackPosition(x, z).distance < 11) continue;
        const tree = new T.Group();
        tree.position.set(x, 0, z);
        tree.rotation.y = random() * Math.PI * 2;
        tree.scale.setScalar(0.7 + random() * 0.85);
        mesh(trunk, bark, tree, 0, 0.7, 0);
        mesh(crown, leaves[i % leaves.length], tree, 0, 2.2, 0);
        scene.add(tree);
      }

      const car = new T.Group();
      scene.add(car);
      const red = material(0xe53530);
      const dark = material(0x1c2934);
      const glass = material(0x6ac5dc);
      mesh(new T.BoxGeometry(1.68, 0.47, 3.05), red, car, 0, 0.53, 0);
      mesh(new T.BoxGeometry(1.27, 0.43, 1.35), glass, car, 0, 0.96, -0.15);
      mesh(new T.BoxGeometry(1.32, 0.10, 1.42), red, car, 0, 1.21, -0.15);
      mesh(new T.BoxGeometry(1.78, 0.12, 0.34), dark, car, 0, 0.82, -1.28);
      const wheel = new T.CylinderGeometry(0.32, 0.32, 0.26, 10);
      const lamp = new T.BoxGeometry(0.33, 0.15, 0.04);
      const white = material(0xfff5c5);
      for (const side of [-1, 1]) {
        for (const axle of [-1, 1]) {
          mesh(wheel, dark, car, side * 0.86, 0.32, axle * 0.99)
            .rotation.z = Math.PI / 2;
        }
        mesh(lamp, white, car, side * 0.54, 0.57, 1.53);
      }

      const shadow = mesh(new T.CircleGeometry(1, 16),
        new T.MeshBasicMaterial({ color: 0x101820, transparent: true, opacity: 0.26 }),
        scene, 0, 0.035, 0);
      shadow.rotation.order = 'YXZ';
      shadow.rotation.x = -Math.PI / 2;
      shadow.scale.set(1.05, 1.65, 1);

      const keys = new Set();
      const controls = new Set([
        'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown',
        'ArrowLeft', 'ArrowRight', 'Space', 'KeyR'
      ]);
      addEventListener('keydown', event => {
        if (!controls.has(event.code)) return;
        event.preventDefault();
        keys.add(event.code);
        if (event.code === 'KeyR' && !event.repeat) reset();
      });
      addEventListener('keyup', event => keys.delete(event.code));
      addEventListener('blur', () => keys.clear());
      document.addEventListener('visibilitychange', () => keys.clear());
      const held = (...codes) => codes.some(code => keys.has(code));

      const storageKey = 'meadow-circuit.best-lap-ms.v1';
      let best = Infinity;
      try {
        const saved = Number(localStorage.getItem(storageKey));
        if (Number.isFinite(saved) && saved > 0) best = saved;
      } catch { /* The game still works when storage is unavailable. */ }

      let yaw, speed, previousProgress, checkpoint, lapStart, laps;
      const gates = [0.25, 0.5, 0.75];
      const follow = new T.Vector3();
      const focus = new T.Vector3();
      const currentDisplay = $('current');
      const bestDisplay = $('best');
      const lapDisplay = $('laps');
      const status = $('status');

      function format(ms) {
        if (!Number.isFinite(ms)) return '—';
        const total = Math.floor(ms);
        const minutes = Math.floor(total / 60000);
        const seconds = String(Math.floor(total / 1000) % 60).padStart(2, '0');
        const fraction = String(total % 1000).padStart(3, '0');
        return `${minutes}:${seconds}.${fraction}`;
      }

      function updateCamera(blend) {
        const x = Math.sin(yaw), z = Math.cos(yaw);
        follow.set(car.position.x - x * 8.5, 5.6, car.position.z - z * 8.5);
        camera.position.lerp(follow, blend);
        focus.set(car.position.x + x * 5, 0.7, car.position.z + z * 5);
        camera.lookAt(focus);
      }

      function reset() {
        yaw = startYaw;
        speed = 0;
        car.position.copy(start).addScaledVector(tangents[0], -3.5);
        car.rotation.y = yaw;
        previousProgress = trackPosition(car.position.x, car.position.z).progress;
        checkpoint = 0;
        lapStart = null;
        laps = 0;
        currentDisplay.textContent = '—';
        bestDisplay.textContent = format(best);
        lapDisplay.textContent = '0';
        status.textContent = 'Cross the line to start the timer.';
        updateCamera(1);
      }

      function updateRace(location, now) {
        const p = location.progress;
        const previous = previousProgress;
        previousProgress = p;

        // A large jump can happen when cutting across the infield.
        // Only small, forward, on-road crossings can advance the race.
        let advance = p - previous;
        if (advance < -0.5) advance += 1;
        if (advance > 0.5) advance -= 1;
        if (location.distance > HALF || advance <= 0 || advance > 0.04) return;

        if (p < previous) {
          if (lapStart !== null && checkpoint === gates.length) {
            const result = now - lapStart;
            laps++;
            lapDisplay.textContent = laps;
            if (result < best) {
              best = result;
              bestDisplay.textContent = format(best);
              try { localStorage.setItem(storageKey, String(best)); } catch {}
              status.textContent = `New best: ${format(result)}!`;
            } else {
              status.textContent = `Last lap: ${format(result)}`;
            }
          } else {
            status.textContent = lapStart === null
              ? 'Lap started. Follow the road!'
              : 'Lap not counted: missed a checkpoint.';
          }
          lapStart = now;
          checkpoint = 0;
        } else if (lapStart !== null && checkpoint < gates.length &&
                   previous < gates[checkpoint] && p >= gates[checkpoint]) {
          checkpoint++;
        }
      }

      function drive(dt, now) {
        const offRoad = trackPosition(car.position.x, car.position.z).distance > HALF;
        const throttle = Number(held('KeyW', 'ArrowUp')) -
                         Number(held('KeyS', 'ArrowDown'));
        const steer = Number(held('KeyD', 'ArrowRight')) -
                      Number(held('KeyA', 'ArrowLeft'));

        if (held('Space')) {
          speed = T.MathUtils.damp(speed, 0, 9, dt);
        } else if (throttle) {
          const target = throttle > 0 ? (offRoad ? 8 : 29) : (offRoad ? -4 : -8);
          speed = T.MathUtils.damp(speed, target, offRoad ? 3.5 : 1.4, dt);
        } else {
          speed = T.MathUtils.damp(speed, 0, offRoad ? 3 : 1, dt);
        }

        const turnGrip = Math.min(Math.abs(speed) / 5, 1);
        const turnRate = 1.95 - 0.65 * Math.min(Math.abs(speed) / 29, 1);
        yaw += steer * Math.sign(speed) * turnGrip * turnRate * dt;
        car.rotation.y = yaw;
        car.position.x += Math.sin(yaw) * speed * dt;
        car.position.z += Math.cos(yaw) * speed * dt;
        // Keep the car within the play area if the player drives into the meadow.
        car.position.x = T.MathUtils.clamp(car.position.x, -95, 95);
        car.position.z = T.MathUtils.clamp(car.position.z, -80, 80);

        updateRace(trackPosition(car.position.x, car.position.z), now);
      }

      reset();
      let previousTime = performance.now();
      renderer.setAnimationLoop(now => {
        const dt = T.MathUtils.clamp((now - previousTime) / 1000, 0, 0.05);
        previousTime = now;
        drive(dt, now);
        shadow.position.x = car.position.x;
        shadow.position.z = car.position.z;
        shadow.rotation.y = yaw;
        updateCamera(1 - Math.exp(-7 * dt));
        if (lapStart !== null) currentDisplay.textContent = format(now - lapStart);
        renderer.render(scene, camera);
      });
    }
  </script>
</body>
</html>
```

### Run it

From the folder containing `index.html`, run `python -m http.server 8000` (or `python3 -m http.server 8000`), then open `http://localhost:8000`. The browser needs internet access to fetch Three.js and WebGL support to render the game.

### How I’d verify it

I haven’t run it here. I’d check the following in a browser:

1. **Startup and controls:** Confirm the track, car, and HUD appear with no console errors. Test both control schemes, braking, and the slowdown on grass. Resize the window and check that the view stays correctly proportioned.
2. **Lap timing:** Cross the checkerboard going forward. The timer should start, but the lap count should stay at zero. Drive a full lap on the road and cross again: the count should become one, the best lap should appear, and the current timer should restart.
3. **Invalid laps:** Cross the line backward, then forward without circling the track. No lap should be added. Cut across the infield so you skip a quarter-track checkpoint and confirm that lap isn’t counted either.
4. **Best lap and reset:** Finish a slower lap and verify the best stays unchanged. Finish a faster one and verify it updates. Press **R**, then reload: each should reset the current run without erasing the saved best.

Save this as `index.html`. It’s a complete single-file racer; the only external dependency is Three.js, loaded from a pinned CDN URL.

**Controls:** W / ↑ to accelerate, S / ↓ to brake or reverse, A / D or ← / → to steer, and R to restart the current lap. Grass slows you down. A lap counts after you pass the three checkpoints in order and cross the finish line heading forward. Your best lap is saved in your browser when local storage is available.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Pine Loop — Arcade Racer</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0; overflow: hidden; background: #a9d9ed;
      color: #fff; font: 15px system-ui, sans-serif;
    }
    canvas { display: block; }
    #hud {
      position: fixed; z-index: 1; top: 16px; left: 16px;
      padding: 14px 18px; border-radius: 10px;
      background: #12251eed; pointer-events: none;
      font-variant-numeric: tabular-nums;
    }
    h1 { margin: 0 0 8px; font-size: 20px; }
    #status, #controls { color: #c7e6d6; }
    #controls { margin-top: 8px; font-size: 12px; }
    #error { margin: 8px 0 0; color: #ffd0a0; }
  </style>
</head>
<body>
  <section id="hud" aria-label="Race dashboard">
    <h1>Pine Loop</h1>
    <div>Lap <strong id="lap">00:00.000</strong></div>
    <div>Best <strong id="best">—</strong></div>
    <div id="status">Cross the start line to begin.</div>
    <div id="controls">WASD / arrows · R to restart</div>
    <p id="error" hidden></p>
  </section>

  <script type="module">
    const error = document.getElementById("error");

    try {
      const THREE = await import(
        "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"
      );
      run(THREE);
    } catch (e) {
      error.hidden = false;
      error.textContent = "Could not start. Check your connection and WebGL support.";
      console.error(e);
    }

    function run(T) {
      const scene = new T.Scene();
      scene.background = new T.Color(0xa9d9ed);
      scene.fog = new T.Fog(0xa9d9ed, 100, 245);

      const camera = new T.PerspectiveCamera(58, 1, 0.1, 320);
      const renderer = new T.WebGLRenderer({ antialias: true });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      document.body.appendChild(renderer.domElement);

      function resize() {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
      }
      window.addEventListener("resize", resize);
      resize();

      scene.add(new T.HemisphereLight(0xe7f5ff, 0x73944d, 2.0));
      const sun = new T.DirectionalLight(0xffefd2, 2.1);
      sun.position.set(-35, 55, -25);
      scene.add(sun);

      function material(color) {
        return new T.MeshStandardMaterial({ color, flatShading: true });
      }

      function mesh(geometry, mat, parent, x, y, z) {
        const object = new T.Mesh(geometry, mat);
        object.position.set(x, y, z);
        parent.add(object);
        return object;
      }

      const ground = mesh(new T.PlaneGeometry(560, 560),
        material(0x669648), scene, 0, 0, 0);
      ground.rotation.x = -Math.PI / 2;

      // Closed oval, sampled into a low-poly road ribbon.
      const TAU = Math.PI * 2;
      const RX = 48, RZ = 30, WIDTH = 10, N = 96;
      function frame(a) {
        const x = RX * Math.cos(a), z = RZ * Math.sin(a);
        const dx = -RX * Math.sin(a), dz = RZ * Math.cos(a);
        const len = Math.hypot(dx, dz);
        const tx = dx / len, tz = dz / len;
        return { x, z, tx, tz, nx: tz, nz: -tx };
      }

      const samples = Array.from({ length: N }, (_, i) => frame(i * TAU / N));
      function ribbon(left, right, height, mat, first = 0, count = N) {
        const vertices = [], indices = [];
        for (let i = 0; i <= count; i++) {
          const p = samples[(first + i) % N];
          for (const offset of [left, right]) {
            vertices.push(p.x + p.nx * offset, height, p.z + p.nz * offset);
          }
          if (i < count) {
            const j = i * 2;
            indices.push(j, j + 2, j + 1, j + 1, j + 2, j + 3);
          }
        }
        const geo = new T.BufferGeometry();
        geo.setAttribute("position", new T.Float32BufferAttribute(vertices, 3));
        geo.setIndex(indices);
        geo.computeVertexNormals();
        mesh(geo, mat, scene, 0, 0, 0);
      }

      const paint = material(0xfff2d6);
      ribbon(-WIDTH / 2, WIDTH / 2, 0.03, material(0x343b41));
      ribbon(-4.8, -4.58, 0.045, paint);
      ribbon(4.58, 4.8, 0.045, paint);
      const yellow = material(0xe6b642);
      for (let i = 3; i < N; i += 4) ribbon(-0.09, 0.09, 0.045, yellow, i, 1);

      const gates = Array.from({ length: 4 }, (_, i) => frame(i * TAU / 4));
      const start = gates[0];
      const tile = new T.BoxGeometry(1, 0.015, 0.55);
      const dark = material(0x171a1c);
      for (let row = 0; row < 2; row++) {
        for (let col = 0; col < WIDTH; col++) {
          mesh(tile, (row + col) % 2 ? paint : dark, scene,
            start.x + col - 4.5, 0.055, (row - 0.5) * 0.55);
        }
      }

      // Use the same sampled centerline as the rendered road for grip.
      const segments = samples.map((p, i) => {
        const q = samples[(i + 1) % N];
        const dx = q.x - p.x, dz = q.z - p.z;
        return { x: p.x, z: p.z, dx, dz, inv: 1 / (dx * dx + dz * dz) };
      });
      function roadDistanceSquared(x, z) {
        let best = Infinity;
        for (const s of segments) {
          const u = T.MathUtils.clamp(
            ((x - s.x) * s.dx + (z - s.z) * s.dz) * s.inv, 0, 1);
          const dx = x - s.x - u * s.dx, dz = z - s.z - u * s.dz;
          best = Math.min(best, dx * dx + dz * dz);
        }
        return best;
      }

      const trunk = new T.CylinderGeometry(0.19, 0.26, 1.6, 5);
      const crown = new T.ConeGeometry(1.35, 3, 5);
      const bark = material(0x785032);
      const leaves = [material(0x295d3b), material(0x39794b)];
      let seed = 7341;
      function random() {
        seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
        return seed / 4294967296;
      }
      for (let i = 0; i < 170; i++) {
        const x = (random() - 0.5) * 185, z = (random() - 0.5) * 150;
        if (roadDistanceSquared(x, z) < 100) continue;
        const tree = new T.Group();
        tree.position.set(x, 0, z);
        tree.rotation.y = random() * TAU;
        tree.scale.setScalar(0.75 + random() * 0.65);
        scene.add(tree);
        mesh(trunk, bark, tree, 0, 0.8, 0);
        const leaf = leaves[i % 2];
        mesh(crown, leaf, tree, 0, 2.35, 0);
        mesh(crown, leaf, tree, 0, 3.35, 0).scale.setScalar(0.72);
      }

      // The car's local +Z axis points forward.
      const car = new T.Group();
      scene.add(car);
      const orange = material(0xff632e);
      mesh(new T.BoxGeometry(1.65, 0.45, 2.8), orange, car, 0, 0.53, 0);
      mesh(new T.BoxGeometry(1.3, 0.48, 1.33),
        material(0x243e52), car, 0, 0.96, -0.18);
      mesh(new T.BoxGeometry(1.55, 0.14, 0.3), orange, car, 0, 0.97, -1.23);
      const tires = new T.CylinderGeometry(0.36, 0.36, 0.28, 8);
      for (const x of [-0.86, 0.86]) {
        for (const z of [-0.91, 0.91]) {
          mesh(tires, dark, car, x, 0.37, z).rotation.z = Math.PI / 2;
        }
      }

      const byId = id => document.getElementById(id);
      const lapDisplay = byId("lap"), bestDisplay = byId("best");
      const status = byId("status");
      const storageKey = "pine-loop-best-v1";
      let best = Infinity;
      try {
        const saved = Number(localStorage.getItem(storageKey));
        if (Number.isFinite(saved) && saved > 0) best = saved;
      } catch { /* Storage is optional. */ }

      function format(seconds) {
        const ms = Math.max(0, Math.floor(seconds * 1000));
        const pad = (n, length = 2) => String(n).padStart(length, "0");
        return `${pad(Math.floor(ms / 60000))}:${pad(Math.floor(ms / 1000) % 60)}.${pad(ms % 1000, 3)}`;
      }
      function showBest() {
        bestDisplay.textContent = Number.isFinite(best) ? format(best) : "—";
      }
      showBest();

      const keys = new Set();
      const controls = new Set([
        "KeyW", "KeyA", "KeyS", "KeyD",
        "ArrowUp", "ArrowLeft", "ArrowDown", "ArrowRight", "KeyR"
      ]);
      window.addEventListener("keydown", e => {
        if (!controls.has(e.code)) return;
        e.preventDefault();
        keys.add(e.code);
        if (e.code === "KeyR" && !e.repeat) reset();
      });
      window.addEventListener("keyup", e => keys.delete(e.code));
      window.addEventListener("blur", () => keys.clear());
      document.addEventListener("visibilitychange", () => keys.clear());
      const pressed = (...codes) => codes.some(code => keys.has(code));

      let x, z, heading, speed, nextGate, lapStart;
      const cameraGoal = new T.Vector3();
      const lookAt = new T.Vector3();

      function updateView(dt, snap = false) {
        car.position.set(x, 0.045, z);
        car.rotation.y = heading;
        const fx = Math.sin(heading), fz = Math.cos(heading);
        cameraGoal.set(x - fx * 9, 6, z - fz * 9);
        camera.position.lerp(cameraGoal, snap ? 1 : 1 - Math.exp(-6 * dt));
        lookAt.set(x + fx * 4, 0.8, z + fz * 4);
        camera.lookAt(lookAt);
      }

      function reset() {
        x = start.x - start.tx * 5;
        z = start.z - start.tz * 5;
        heading = Math.atan2(start.tx, start.tz);
        speed = 0;
        nextGate = 0;
        lapStart = null;
        lapDisplay.textContent = format(0);
        status.textContent = "Cross the start line to begin.";
        updateView(0, true);
      }
      reset();

      // Intersect the car's movement segment with the expected gate.
      // Require a forward crossing within the width of the track.
      function checkGate(oldX, oldZ, time, dt) {
        const g = gates[nextGate];
        const a = (oldX - g.x) * g.tx + (oldZ - g.z) * g.tz;
        const b = (x - g.x) * g.tx + (z - g.z) * g.tz;
        if (a >= 0 || b < 0 || speed <= 0) return;
        const u = -a / (b - a);
        const crossX = oldX + (x - oldX) * u;
        const crossZ = oldZ + (z - oldZ) * u;
        if (Math.abs((crossX - g.x) * g.nx + (crossZ - g.z) * g.nz) > WIDTH / 2) return;

        if (nextGate === 0) {
          const crossingTime = time - dt * (1 - u);
          let message = "Checkpoint 0 / 3";
          if (lapStart !== null) {
            const result = crossingTime - lapStart;
            if (result < best) {
              best = result;
              showBest();
              try { localStorage.setItem(storageKey, String(best)); } catch {}
              message = "New best! " + format(result);
            } else {
              message = "Last lap: " + format(result);
            }
          }
          lapStart = crossingTime;
          status.textContent = message;
        } else {
          status.textContent = `Checkpoint ${nextGate} / 3`;
        }
        nextGate = (nextGate + 1) % gates.length;
      }

      let last = null;
      let simulationTime = 0;
      document.addEventListener("visibilitychange", () => { last = null; });

      function animate(now) {
        requestAnimationFrame(animate);
        const dt = last === null || document.hidden ? 0 :
          Math.min((now - last) / 1000, 0.05);
        last = now;
        simulationTime += dt;

        if (dt > 0) {
          const offRoad = roadDistanceSquared(x, z) > (WIDTH / 2) ** 2;
          const throttle = Number(pressed("KeyW", "ArrowUp")) -
                           Number(pressed("KeyS", "ArrowDown"));
          const steer = Number(pressed("KeyA", "ArrowLeft")) -
                        Number(pressed("KeyD", "ArrowRight"));
          const opposing = throttle * speed < 0;
          speed += throttle * (opposing ? 36 : offRoad ? 8 : 18) * dt;
          speed *= Math.exp(-(offRoad ? 2.6 : throttle ? 0.43 : 1.25) * dt);
          speed = T.MathUtils.clamp(speed, -8, 31);
          heading += steer * Math.sign(speed) *
            Math.min(Math.abs(speed) / 5, 1) * (offRoad ? 1.7 : 2.05) * dt;

          const oldX = x, oldZ = z;
          x += Math.sin(heading) * speed * dt;
          z += Math.cos(heading) * speed * dt;
          checkGate(oldX, oldZ, simulationTime, dt);
          if (lapStart !== null) lapDisplay.textContent = format(simulationTime - lapStart);
        }

        updateView(dt);
        renderer.render(scene, camera);
      }
      requestAnimationFrame(animate);
    }
  </script>
</body>
</html>
```

