</head>
<body>
  <header>
    <h1>Dune Loop</h1>
    <dl>
      <dt>Current lap</dt><dd id="lap">--:--.---</dd>
      <dt>Best lap</dt><dd id="best">--:--.---</dd>
    </dl>
    <p id="status" role="status">Loading Three.js…</p>
  </header>
  <footer>W / ↑ Gas · S / ↓ Brake or reverse · A D / ← → Steer · R Reset</footer>

  <script type="module">
    const lapDisplay = document.querySelector('#lap');
    const bestDisplay = document.querySelector('#best');
    const status = document.querySelector('#status');

    try {
      const THREE = await import('https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js');
      start(THREE);
    } catch (error) {
      status.textContent = 'Could not start. Check your connection and WebGL support.';
      console.error(error);
    }

    function start(T) {
      const TAU = Math.PI * 2;
      const segments = 96;
      const track = { inner: 24, outer: 36, middle: 30 };
      const storageKey = 'dune-loop.best.v1';
      const clamp = T.MathUtils.clamp;
      const scene = new T.Scene();
      scene.background = new T.Color(0xf4be87);
      scene.fog = new T.Fog(0xf4be87, 65, 165);

      const camera = new T.PerspectiveCamera(62, 1, 0.1, 220);
      const renderer = new T.WebGLRenderer({ antialias: true });
      document.body.append(renderer.domElement);
      function resize() {
        camera.aspect = innerWidth / innerHeight;
        camera.updateProjectionMatrix();
        renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
        renderer.setSize(innerWidth, innerHeight);
      }
      window.addEventListener('resize', resize);
      resize();

      scene.add(new T.HemisphereLight(0xfff0d1, 0x9c654b, 2));
      const sun = new T.DirectionalLight(0xffe1bb, 2.3);
      sun.position.set(-25, 45, 12);
      scene.add(sun);

      function mesh(geometry, color, parent = scene) {
        const object = new T.Mesh(geometry, new T.MeshStandardMaterial({
          color, roughness: 0.9, flatShading: true
        }));
        parent.add(object);
        return object;
      }

      function box(parent, color, w, h, d, x, y, z) {
        const object = mesh(new T.BoxGeometry(w, h, d), color, parent);
        object.position.set(x, y, z);
        return object;
      }

      function ring(inner, outer, y, color) {
        const object = mesh(new T.RingGeometry(inner, outer, segments), color);
        object.rotation.x = -Math.PI / 2;
        object.position.y = y;
        return object;
      }

      box(scene, 0xce8a55, 300, 1, 300, 0, -0.54, 0);
      ring(track.inner, track.outer, 0, 0x343d43);
      ring(track.inner, track.inner + 0.23, 0.02, 0xffdc9f);
      ring(track.outer - 0.23, track.outer, 0.02, 0xffdc9f);

      for (let i = 0; i < segments; i++) {
        const a = i * TAU / segments;
        const x = Math.cos(a), z = Math.sin(a);
        for (const r of [track.inner - 0.27, track.outer + 0.27]) {
          box(scene, i % 2 ? 0xffe1b8 : 0xc94c30, 0.55, 0.42, 2.42,
            x * r, 0.21, z * r).rotation.y = -a;
        }
        if (i && i % 3 === 0) {
          box(scene, 0xb9b9a7, 0.10, 0.025, 1.75,
            x * track.middle, 0.015, z * track.middle).rotation.y = -a;
        }
      }

      for (let i = 0; i < 12; i++) {
        for (let row = 0; row < 2; row++) {
          box(scene, (i + row) % 2 ? 0x151b20 : 0xfff8e3,
            1, 0.03, 0.55, track.inner + i + 0.5, 0.025, (row - 0.5) * 0.55);
        }
      }

      for (let i = 0; i < 36; i++) {
        const a = i * 2.399963;
        const r = i % 3 === 0 ? 7 + i % 11 : 47 + (i * 13) % 51;
        const h = 1.5 + (i * 7) % 9;
        const rock = mesh(new T.ConeGeometry(1.2 + (i % 5) * 0.7, h, 5),
          [0xb76342, 0xdd9860, 0x9f543b][i % 3]);
        rock.position.set(r * Math.cos(a), h / 2 - 0.05, r * Math.sin(a));
        rock.rotation.y = a;
      }

      const model = new T.Group();
      scene.add(model);
      box(model, 0x1bc3ae, 1.65, 0.48, 2.85, 0, 0.56, 0);
      box(model, 0x253b46, 1.26, 0.43, 1.28, 0, 0.97, -0.18);
      box(model, 0x1bc3ae, 1.15, 0.09, 1.05, 0, 1.21, -0.18);
      for (const x of [-0.81, 0.81]) {
        for (const z of [-0.90, 0.90]) {
          const wheel = mesh(new T.CylinderGeometry(0.32, 0.32, 0.32, 8), 0x1b2228, model);
          wheel.rotation.z = Math.PI / 2;
          wheel.position.set(x, 0.32, z);
        }
        box(model, 0xff4f36, 0.28, 0.14, 0.04, x * 0.72, 0.59, -1.44);
      }

      const car = { x: 0, z: 0, heading: 0, speed: 0 };
      const lap = { angle: 0, progress: 0, startedAt: null };
      let best = Infinity;
      try {
        const saved = Number(localStorage.getItem(storageKey));
        if (Number.isFinite(saved) && saved > 0) best = saved;
      } catch {}

      function format(ms) {
        const n = Math.max(0, Math.floor(ms));
        const pad = (value, digits) => String(value).padStart(digits, '0');
        return `${pad(Math.floor(n / 60000), 2)}:${pad(Math.floor(n / 1000) % 60, 2)}.${pad(n % 1000, 3)}`;
      }
      if (Number.isFinite(best)) bestDisplay.textContent = format(best);

      const keys = new Set();
      const controls = new Set([
        'KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyR',
        'ArrowUp', 'ArrowLeft', 'ArrowDown', 'ArrowRight'
      ]);
      const down = (a, b) => keys.has(a) || keys.has(b);
      window.addEventListener('keydown', event => {
        if (!controls.has(event.code)) return;
        event.preventDefault();
        if (event.code === 'KeyR' && !event.repeat) reset();
        else keys.add(event.code);
      });
      window.addEventListener('keyup', event => keys.delete(event.code));
      window.addEventListener('blur', () => keys.clear());
      document.addEventListener('visibilitychange', () => {
        if (document.hidden) keys.clear();
      });

      const eye = new T.Vector3();
      const target = new T.Vector3();
      function updateView(blend) {
        const fx = Math.sin(car.heading), fz = Math.cos(car.heading);
        model.position.set(car.x, 0, car.z);
        model.rotation.y = car.heading;
        eye.set(car.x - fx * 8, 5.3, car.z - fz * 8);
        target.set(car.x + fx * 4, 0.65, car.z + fz * 4);
        camera.position.lerp(eye, blend);
        camera.lookAt(target);
      }

      function reset() {
        Object.assign(car, { x: track.middle, z: -3, heading: 0, speed: 0 });
        Object.assign(lap, { angle: Math.atan2(car.z, car.x), progress: 0, startedAt: null });
        lapDisplay.textContent = '--:--.---';
        status.textContent = 'Cross the checkerboard to start.';
        updateView(1);
      }

      function updateLap(previousTime, now) {
        const angle = Math.atan2(car.z, car.x);
        const change = Math.atan2(Math.sin(angle - lap.angle), Math.cos(angle - lap.angle));
        const before = lap.startedAt === null ? lap.angle : lap.progress;
        const finish = lap.startedAt === null ? 0 : TAU;
        const after = before + change;
        lap.angle = angle;

        if (change > 0 && before < finish && after >= finish) {
          const crossing = previousTime + (now - previousTime) * (finish - before) / change;
          if (lap.startedAt !== null) {
            const elapsed = crossing - lap.startedAt;
            const record = elapsed < best;
            if (record) {
              best = elapsed;
              bestDisplay.textContent = format(best);
              try { localStorage.setItem(storageKey, String(best)); } catch {}
            }
            status.textContent = `${record ? 'New best' : 'Last lap'} ${format(elapsed)}`;
          } else {
            status.textContent = 'Timer running.';
          }
          lap.startedAt = crossing;
          lap.progress = after - finish;
        } else if (lap.startedAt !== null) {
          lap.progress = after;
        }
        if (lap.startedAt !== null) lapDisplay.textContent = format(now - lap.startedAt);
      }

      function drive(dt) {
        const gas = down('KeyW', 'ArrowUp');
        const brake = down('KeyS', 'ArrowDown');
        const steer = Number(down('KeyD', 'ArrowRight')) - Number(down('KeyA', 'ArrowLeft'));

        if (gas && !brake) car.speed += (car.speed < 0 ? 28 : 15) * dt;
        else if (brake) car.speed -= (car.speed > 0.5 ? 32 : 9) * dt;
        else car.speed *= Math.exp(-1.35 * dt);
        car.speed = clamp(car.speed, -8, 26);
        car.heading -= steer * Math.sign(car.speed) *
          clamp(Math.abs(car.speed) / 5, 0, 1) * 1.7 * dt;
        car.x += Math.sin(car.heading) * car.speed * dt;
        car.z += Math.cos(car.heading) * car.speed * dt;

        const radius = Math.hypot(car.x, car.z);
        const safe = clamp(radius, track.inner + 1.45, track.outer - 1.45);
        if (safe !== radius) {
          car.x *= safe / radius;
          car.z *= safe / radius;
          car.speed *= Math.exp(-10 * dt);
        }
      }

      reset();
      let previous = performance.now();
      function frame(now) {
        const dt = clamp((now - previous) / 1000, 0, 0.05);
        drive(dt);
        updateLap(Math.max(previous, now - dt * 1000), now);
        updateView(1 - Math.exp(-8 * dt));
        renderer.render(scene, camera);
        previous = now;
        requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }
  </script>
