        car.rotation.y = heading;
        desiredCamera.set(x - fx * 8, 5.6, z - fz * 8);
        camera.position.lerp(desiredCamera, snap ? 1 : 1 - Math.exp(-8 * dt));
        target.set(x + fx * 3, 0.85, z + fz * 3);
        camera.lookAt(target);
        lapLabel.textContent = clockLabel(state.elapsed);
        renderer.render(scene, camera);
      }

      function reset() {
        Object.assign(state, {
          x: radius(0), z: 0, angle: 0,
          heading: Math.atan2(9, radius(0)),
          speed: 0, progress: 0, elapsed: 0, running: false
        });
        lastLabel.textContent = clockLabel(null);
        status.textContent = 'Accelerate to start the clock';
        draw(0, true);
      }

      addEventListener('keydown', event => {
        if (!controls.has(event.code)) return;
        event.preventDefault();
        if (event.code === 'KeyR') {
          if (!event.repeat) reset();
        } else {
          keys.add(event.code);
        }
      });
      addEventListener('keyup', event => keys.delete(event.code));
      addEventListener('blur', () => keys.clear());

      function step(dt) {
        const gas = held('KeyW', 'ArrowUp');
        const brake = held('KeyS', 'ArrowDown');
        const steer = Number(held('KeyD', 'ArrowRight'))
          - Number(held('KeyA', 'ArrowLeft'));

        if (!state.running && (gas || brake)) {
          state.running = true;
          status.textContent = 'Lap in progress';
        }
        if (!state.running) return;

        if (brake) state.speed -= (state.speed > 0 ? 32 : 12) * dt;
        else if (gas) state.speed += (state.speed < 0 ? 26 : 17) * dt;
        else state.speed *= Math.exp(-1.35 * dt);
        state.speed = clamp(state.speed, -8, 27);

        const turn = Math.min(Math.abs(state.speed) / 4, 1);
        state.heading += steer * turn * Math.sign(state.speed) * 1.9 * dt;
        const x = state.x + Math.sin(state.heading) * state.speed * dt;
        const z = state.z + Math.cos(state.heading) * state.speed * dt;
        const angle = Math.atan2(z, x);
        const r = Math.hypot(x, z);
        const mid = radius(angle);
        const limit = HALF_WIDTH - 0.85;
        const onRoad = clamp(r, mid - limit, mid + limit);
        if (onRoad !== r) state.speed *= Math.exp(-5 * dt);
        state.x = Math.cos(angle) * onRoad;
        state.z = Math.sin(angle) * onRoad;

        const delta = angle - state.angle;
        const travel = Math.atan2(Math.sin(delta), Math.cos(delta));
        const previous = state.progress;
        state.progress += travel;
        state.angle = angle;
        state.elapsed += dt;

        if (state.progress >= TAU) {
          const remainder = dt * (1 - clamp((TAU - previous) / travel, 0, 1));
          const time = state.elapsed - remainder;
          lastLabel.textContent = clockLabel(time);
          if (best === null || time < best) {
            best = time;
            bestLabel.textContent = clockLabel(best);
            status.textContent = 'New best lap';
            try {
              localStorage.setItem(BEST_KEY, String(best));
            } catch {
              // Keep the session best if storage is unavailable.
            }
          } else {
            status.textContent = 'Lap complete';
          }
          state.progress -= TAU;
          state.elapsed = remainder;
        }
      }

      let previousFrame = null;
      document.addEventListener('visibilitychange', () => {
        previousFrame = null;
        keys.clear();
      });

      function frame(now) {
        const dt = previousFrame === null ? 0 : Math.min((now - previousFrame) / 1000, 0.1);
        previousFrame = now;
        if (!document.hidden) {
          const steps = Math.max(1, Math.ceil(dt * 120));
          for (let i = 0; i < steps; i++) step(dt / steps);
          draw(dt);
        }
        requestAnimationFrame(frame);
      }

      reset();
      requestAnimationFrame(frame);
    }
  </script>
</body>
</html>
```

### Run and verify

Open `index.html` in a current desktop browser with WebGL enabled and internet access for the Three.js import. For a consistent origin when testing saved times, serve the file with `python -m http.server 8000` from its directory and open `http://localhost:8000/`.

I did not run the game here. These are the browser checks I would use. The expected results are inferred from the code, not measured.

| Check | Expected result |
|---|---|
| Load and resize the page | The car starts on the checkered line. The road and HUD stay visible, and the console has no errors. |
| Drive with both key sets | WASD and the arrows behave the same. Brake before reversing. The road edge slows the car and keeps it on the track. |
| Drive a complete forward lap | The clock starts on throttle. At the finish, Last and Best show the first lap time and the next lap clock starts. |
| Reverse across the line, then drive forward across it | No lap registers unless the car completes a full net forward circuit. |
| Drive a slower lap, then a faster one | Last changes after both laps. Best changes only after the faster lap. |
| Press R, then reload from the same local-server URL | R returns the car to the grid and clears Lap and Last. Best survives both actions when storage is enabled. |
| Switch tabs while holding throttle, then return | The clock excludes the hidden interval, and throttle stays released until you press it again. |

Save this as `index.html` to play a low-poly time trial on one closed circuit. Use **WASD** or the **arrow keys** to drive and **R** to restart. The current lap and best lap appear above the track. The best lap persists when browser storage is available.

The game is self-contained apart from a pinned Three.js CDN import. I reviewed the code statically, but couldn't run it in a browser here.

### Design and throughput checkpoint

**Data shape.** The track is a loop of sampled points with one shared road-width rule. The car stores position, heading and speed. The lap stores its start time and next required gate, while the best time is stored separately. **Model the domain** led to the ordered gate state instead of a collection of checkpoint flags.

| Approach | Decision |
|---|---|
| Free steering on an oval | Chosen. The same ellipse coordinates define the road, off-road detection and lap gates. |
| Steering constrained to a spline | Rejected. It simplifies lap tracking but removes the ability to miss a turn. |

- **Blocking first steps.** Define the track coordinates and what counts as a valid lap before drawing the road or wiring the timer.
- **Independent workstreams.** The scene and HUD use separate functions, but ship in one file.
- **Shared mutable state.** One animation loop owns car and lap updates.
- **Smallest safe decomposition.** One HTML file keeps setup small. No repository edits, commits or PR are needed.

