    p { margin: 0; font-size: .85rem; }
    #status { color: #ffd189; }
    #view { height: 68vh; min-height: 240px; }
    canvas { display: block; width: 100%; height: 100%; }
  </style>
</head>
<body>
  <header>
    <h1>Mesa Circuit</h1>
    <dl>
      <div><dt>Current lap</dt><dd id="current">--:--.---</dd></div>
      <div><dt>Best lap</dt><dd id="best">--:--.---</dd></div>
    </dl>
    <p>WASD or arrows to drive. R to restart.</p>
    <p id="status" role="status">Loading the circuit…</p>
  </header>
  <main id="view" aria-label="3D race view"></main>

  <script type="module">
    const view = document.querySelector("#view");
    const current = document.querySelector("#current");
    const bestDisplay = document.querySelector("#best");
    const status = document.querySelector("#status");

    try {
      const THREE = await import(
        "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"
      );
      startGame(THREE);
    } catch (error) {
      status.textContent = "Could not load the game. Check your connection and WebGL support, then reload.";
      console.error(error);
    }

    function startGame(T) {
      const TAU = Math.PI * 2;
      const A = 58, B = 36, WIDTH = 0.15, SEGMENTS = 96;
      const storageKey = "mesa-circuit-best-ms-v1";
      const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");
      const keys = new Set();
      const car = { x: 0, z: 0, yaw: 0, speed: 0 };
      const lap = { start: null, next: 0 };
      let best = null;

      try {
        const saved = Number(localStorage.getItem(storageKey));
        if (Number.isFinite(saved) && saved > 0) best = saved;
      } catch {}

      const renderer = new T.WebGLRenderer({ antialias: true });
      renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
      view.append(renderer.domElement);

      const scene = new T.Scene();
      scene.background = new T.Color(0xf1b879);
      scene.fog = new T.Fog(0xf1b879, 85, 220);
      const camera = new T.PerspectiveCamera(58, 1, 0.1, 350);

      scene.add(new T.HemisphereLight(0xffedd3, 0x765148, 2.1));
      const sun = new T.DirectionalLight(0xffdbac, 2.4);
      sun.position.set(-35, 65, 25);
      scene.add(sun);

      const material = color => new T.MeshStandardMaterial({
        color, roughness: 1, flatShading: true, side: T.DoubleSide
      });

      function box(parent, mat, w, h, d, x, y, z) {
        const mesh = new T.Mesh(new T.BoxGeometry(w, h, d), mat);
        mesh.position.set(x, y, z);
        parent.add(mesh);
        return mesh;
      }

      function strip(inner, outer, start, end, count, y, mat) {
        const vertices = [];
        const point = (angle, radius) => [
          A * Math.cos(angle) * radius, y, B * Math.sin(angle) * radius
        ];
        for (let i = 0; i < count; i++) {
          const a = start + (end - start) * i / count;
          const b = start + (end - start) * (i + 1) / count;
          const p = point(a, inner), q = point(a, outer);
          const r = point(b, inner), s = point(b, outer);
          vertices.push(...p, ...r, ...q, ...q, ...r, ...s);
        }
        const geometry = new T.BufferGeometry();
        geometry.setAttribute("position", new T.Float32BufferAttribute(vertices, 3));
        geometry.computeVertexNormals();
        scene.add(new T.Mesh(geometry, mat));
      }

      box(scene, material(0xb96c43), 600, 1, 600, 0, -.52, 0);
      strip(1 - WIDTH, 1 + WIDTH, 0, TAU, SEGMENTS, .02, material(0x333b46));

      const cream = material(0xffebc4), red = material(0xd44e36);
      const dark = material(0x171c23);
      for (let i = 0; i < 48; i++) {
        const a = TAU * i / 48, b = TAU * (i + 1) / 48;
        const curb = i % 2 ? cream : red;
        strip(.85, .875, a, b, 2, .045, curb);
        strip(1.125, 1.15, a, b, 2, .045, curb);
        strip(.996, 1.004, a + .03, a + .085, 2, .04, cream);
      }

      const tile = 2 * A * WIDTH / 12;
      for (let row = 0; row < 2; row++) {
        for (let col = 0; col < 12; col++) {
          box(scene, (row + col) % 2 ? dark : cream,
            tile, .04, .47, A * (1 - WIDTH) + tile * (col + .5),
            .05, (row - .5) * .47);
        }
      }

      const rock = material(0x98513d);
      const rockGeometry = new T.DodecahedronGeometry(1);
      for (let i = 0; i < 48; i++) {
        const a = i * 2.399963;
        const radius = i % 3 === 0 ? .35 + .007 * i : 1.35 + .015 * (i % 16);
        const mesh = new T.Mesh(rockGeometry, rock);
        const size = 1 + (i * 17 % 11) * .37;
        mesh.scale.set(size, size * (1 + i % 3 * .3), size * .85);
        mesh.position.set(A * radius * Math.cos(a), size * .32, B * radius * Math.sin(a));
        mesh.rotation.y = a;
        scene.add(mesh);
      }

      const model = new T.Group();
      scene.add(model);
      const paint = material(0x25d4bf);
      box(model, paint, 1.95, .55, 3.5, 0, .62, 0);
      box(model, material(0x204357), 1.42, .51, 1.55, 0, 1.08, -.18);
      box(model, cream, 1.73, .14, .25, 0, .66, 1.72);
      for (const x of [-.98, .98]) {
        for (const z of [-1.12, 1.12]) {
          box(model, dark, .42, .64, .72, x, .36, z);
        }
        box(model, red, .43, .18, .09, x * .75, .67, -1.77);
      }

      function format(ms) {
        if (ms === null) return "--:--.---";
        const n = Math.floor(ms);
        const pad = (value, length) => String(value).padStart(length, "0");
        return `${pad(Math.floor(n / 60000), 2)}:${pad(Math.floor(n / 1000) % 60, 2)}.${pad(n % 1000, 3)}`;
      }

      function reset() {
        const a = -.14;
        car.x = A * Math.cos(a);
        car.z = B * Math.sin(a);
        car.yaw = Math.atan2(-A * Math.sin(a), B * Math.cos(a));
        car.speed = 0;
        lap.start = null;
        lap.next = 0;
        status.textContent = "Cross the checkered line to start.";
      }

      const angle = () => Math.atan2(car.z / B, car.x / A);
      const onRoad = () => Math.abs(Math.hypot(car.x / A, car.z / B) - 1) <= WIDTH;

      function updateLap(before, after, now, dtMs) {
        const travel = Math.atan2(Math.sin(after - before), Math.cos(after - before));
        if (travel <= 0) return;
        const gate = lap.next * Math.PI / 2;
        const distance = ((gate - before) % TAU + TAU) % TAU;
        if (distance > travel) return;
        const crossing = now - dtMs * (1 - distance / travel);

        if (lap.next === 0) {
          if (lap.start !== null) {
            const time = crossing - lap.start;
            if (best === null || time < best) {
              best = time;
              bestDisplay.textContent = format(best);
              try { localStorage.setItem(storageKey, String(best)); } catch {}
              status.textContent = `New best lap: ${format(time)}`;
            } else {
              status.textContent = `Last lap: ${format(time)}`;
            }
          } else {
            status.textContent = "Lap started. Stay on the road.";
          }
          lap.start = crossing;
        }
        lap.next = (lap.next + 1) % 4;
      }

      const controls = new Set([
        "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight",
        "KeyW", "KeyA", "KeyS", "KeyD", "KeyR"
      ]);
      addEventListener("keydown", event => {
        if (!controls.has(event.code) || event.ctrlKey || event.metaKey || event.altKey) return;
        event.preventDefault();
        if (event.code === "KeyR" && !event.repeat) reset();
        keys.add(event.code);
      });
      addEventListener("keyup", event => keys.delete(event.code));
      addEventListener("blur", () => keys.clear());
      document.addEventListener("visibilitychange", () => keys.clear());

      const pressed = (a, b) => Number(keys.has(a) || keys.has(b));
      const target = new T.Vector3();

      function render(dt) {
        model.position.set(car.x, .04, car.z);
        model.rotation.y = car.yaw;
        const fx = Math.sin(car.yaw), fz = Math.cos(car.yaw);
        if (reducedMotion.matches) {
          camera.position.set(0, 135, -100);
          camera.lookAt(0, 0, 0);
        } else {
          target.set(car.x - fx * 10, 6.2, car.z - fz * 10);
          camera.position.lerp(target, 1 - Math.exp(-9 * dt));
          camera.lookAt(car.x + fx * 8, .6, car.z + fz * 8);
        }
        renderer.render(scene, camera);
      }

      function resize() {
        const w = Math.max(1, view.clientWidth), h = Math.max(1, view.clientHeight);
        renderer.setSize(w, h, false);
        camera.aspect = w / h;
        camera.updateProjectionMatrix();
      }

      reset();
      bestDisplay.textContent = format(best);
      camera.position.set(car.x, 6.2, car.z - 10);
      new ResizeObserver(resize).observe(view);
      resize();

      let previous = performance.now();
      function frame() {
        const now = performance.now();
        const dt = Math.min((now - previous) / 1000, .05);
        previous = now;

        const throttle = pressed("ArrowUp", "KeyW") - pressed("ArrowDown", "KeyS");
        const steer = pressed("ArrowLeft", "KeyA") - pressed("ArrowRight", "KeyD");
        const before = angle();
        const wasOnRoad = onRoad();
        const limit = wasOnRoad ? 33 : 10;
        car.speed += throttle * 25 * dt;
        car.speed *= Math.exp(-(throttle ? .45 : 1.65) * dt);
        car.speed = T.MathUtils.clamp(car.speed, -limit * .35, limit);
        car.yaw += steer * 1.75 * dt * T.MathUtils.clamp(car.speed / 9, -1, 1);
        car.x += Math.sin(car.yaw) * car.speed * dt;
        car.z += Math.cos(car.yaw) * car.speed * dt;

        if (Math.hypot(car.x / A, car.z / B) > 2.5) {
          reset();
        } else if (!onRoad()) {
          if (lap.start !== null) {
            status.textContent = "Lap invalid. Cross the line to try again.";
          }
          lap.start = null;
          lap.next = 0;
        } else if (wasOnRoad) {
          updateLap(before, angle(), now, dt * 1000);
        }

        current.textContent = format(lap.start === null ? null : now - lap.start);
        render(dt);
        requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }
  </script>
</body>
