  }

  box(scene, material(0xbd925e), 420, 0.5, 420, 0, -0.27, 0);
  const road = [material(0x303941), material(0x343e46)];
  const cream = material(0xffefcf), red = material(0xb84435);
  const dark = material(0x151b20), yellow = material(0xffc36b);
  const segments = 120;

  for (let i = 0; i < segments; i++) {
    const a = i * TAU / segments, b = (i + 1) * TAU / segments;
    strip(a, b, -WIDTH, WIDTH, 0.01, road[Math.floor(i / 4) % 2]);
    const curb = Math.floor(i / 2) % 2 ? red : cream;
    strip(a, b, -WIDTH - 0.35, -WIDTH, 0.02, curb);
    strip(a, b, WIDTH, WIDTH + 0.35, 0.02, curb);
    if (i % 4 === 2) strip(a, (a + b) / 2, -0.07, 0.07, 0.025, yellow);
  }

  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 12; col++) {
      const x = -WIDTH + col * 2 * WIDTH / 12;
      strip((row - 1) * 0.014, row * 0.014, x, x + 2 * WIDTH / 12,
        0.035, (row + col) % 2 ? cream : dark);
    }
  }

  const rockMat = [material(0x9d6953), material(0xd5a271), material(0x7b6155)];
  for (let i = 0; i < 52; i++) {
    const a = i * TAU / 52;
    const offset = i % 3 === 0 ? -13 - i % 6 : 12 + (i * 7) % 20;
    const rock = new T.Mesh(new T.DodecahedronGeometry(1), rockMat[i % 3]);
    rock.position.copy(point(a, offset, 0.5));
    rock.scale.set(1.1 + i % 4 * 0.55, 0.8 + i % 5 * 0.35, 1.3);
    rock.rotation.y = i * 0.7;
    scene.add(rock);
  }

  const car = new T.Group();
  const orange = material(0xfe713e), glass = material(0x294750);
  box(car, orange, 1.65, 0.48, 2.9, 0, 0.46, 0);
  box(car, glass, 1.24, 0.43, 1.23, 0, 0.88, -0.18);
  box(car, cream, 1.27, 0.10, 1.24, 0, 1.12, -0.18);
  for (const side of [-1, 1]) {
    for (const axle of [-1, 1]) {
      box(car, dark, 0.32, 0.56, 0.65, side * 0.85, 0.30, axle * 0.91);
    }
    box(car, cream, 0.35, 0.15, 0.07, side * 0.54, 0.50, 1.48);
    box(car, red, 0.35, 0.16, 0.07, side * 0.54, 0.51, -1.48);
  }
  scene.add(car);

  function resize() {
    camera.aspect = innerWidth / innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(innerWidth, innerHeight);
  }
  addEventListener("resize", resize);
  resize();

  const controls = new Set([
    "KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowDown",
    "ArrowLeft", "ArrowRight", "KeyR"
  ]);
  addEventListener("keydown", event => {
    if (!controls.has(event.code)) return;
    event.preventDefault();
    keys.add(event.code);
    if (event.code === "KeyR" && !event.repeat) {
      race = freshRace();
      snapCamera = true;
    }
  });
  addEventListener("keyup", event => keys.delete(event.code));
  addEventListener("blur", () => keys.clear());

  const held = (a, b) => Number(keys.has(a) || keys.has(b));

  function drive(dt) {
    const throttle = held("KeyW", "ArrowUp") - held("KeyS", "ArrowDown");
    const steer = held("KeyD", "ArrowRight") - held("KeyA", "ArrowLeft");
    if (throttle && dt > 0) race.started = true;

    const shoulder = Math.abs(race.offset) > WIDTH - 0.8;
    const topSpeed = shoulder ? 14 : 35;
    race.speed += throttle * (throttle * race.speed < 0 ? 34 : 18) * dt;
    race.speed *= Math.exp(-(throttle ? 0.36 : 1.5) * dt);
    race.speed = clamp(race.speed, -9, topSpeed);

    // At this track's winding direction, the outside is to the driver's left.
    const target = -steer * clamp(race.speed / 12, -1, 1) * 8;
    race.lateral += (target - race.lateral) * (1 - Math.exp(-8 * dt));
    const offset = race.offset + race.lateral * dt;
    race.offset = clamp(offset, -WIDTH, WIDTH);
    if (offset !== race.offset) race.lateral = 0;

    const previous = race.angle;
    const a = previous % TAU;
    const r = 38 + 5 * Math.cos(3 * a) + 3 * Math.sin(2 * a) + race.offset;
    const dr = -15 * Math.sin(3 * a) + 6 * Math.cos(2 * a);
    race.angle += race.speed * dt / Math.hypot(r, dr);

    if (!race.started) return;
    if (race.angle >= race.finish && previous < race.finish) {
      const fraction = (race.finish - previous) / (race.angle - previous);
      const completed = race.elapsed + dt * fraction;
      if (best === null || completed < best) {
        best = completed;
        try { localStorage.setItem(STORE, String(best)); } catch {}
      }
      race.lap++;
      race.finish += TAU;
      race.elapsed = dt * (1 - fraction);
    } else {
      race.elapsed += dt;
    }
  }

  function clock(seconds) {
    const ms = Math.floor(seconds * 1000);
    return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60)
      .padStart(2, "0")}.${String(ms % 1000).padStart(3, "0")}`;
  }

  function render(dt) {
    const a = race.angle % TAU;
    car.position.copy(point(a, race.offset));
    const forward = point(a + 0.002, race.offset)
      .sub(point(a - 0.002, race.offset)).normalize();
    // The model's nose is local +Z. Keep the camera facing down the track in reverse.
    car.rotation.y = Math.atan2(forward.x, forward.z) +
      Math.atan2(race.lateral, Math.max(8, Math.abs(race.speed))) * 0.8;

    const eye = car.position.clone().addScaledVector(forward, -8);
    eye.y += 5;
    camera.position.lerp(eye, snapCamera ? 1 : 1 - Math.exp(-7 * dt));
    snapCamera = false;
    const aim = car.position.clone().addScaledVector(forward, 7);
    aim.y = 0.9;
    camera.lookAt(aim);

    lapText.textContent = race.lap;
    timeText.textContent = clock(race.elapsed);
    bestText.textContent = best === null ? "--" : clock(best);
    renderer.render(scene, camera);
  }

  let last = null;
  document.addEventListener("visibilitychange", () => {
    keys.clear();
    last = null;
  });
  function frame(now) {
    const dt = last === null || document.hidden ? 0 : Math.min((now - last) / 1000, 0.05);
    last = now;
    drive(dt);
    render(dt);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}
</script>
</body>
</html>
```

### How I would verify it

These are expected results, not measured results.

1. **Load the game.** Check that the road, checkered line, car, and HUD appear. Check DevTools for console errors. If the browser restricts the CDN import or storage for local files, serve the same file over localhost and retry.
2. **Drive both key layouts.** Confirm that both sets of keys accelerate, brake, reverse, and steer. Drive onto either curb and check that the car slows and cannot leave the track. Release the throttle and wait for the car to stop.
3. **Check the finish rule.** Reverse over the starting stripe, then drive forward across it. The lap should still be 1 and Best should still be blank. Drive a full forward circuit. The lap should become 2, Time should roll over, and Best should show the completed lap.
4. **Check the record.** Complete a slower lap and confirm that Best stays unchanged. Then beat it and confirm that Best updates. Press R and reload on the same origin. The run should restart at lap 1 while Best remains.
5. **Check focus and layout.** Hold accelerate, switch tabs, release it, and return. The key should not stick and the hidden time should not be added. Resize the window and check that the scene keeps its proportions and the controls remain readable.

**Mesa Loop** is a single-file Three.js time trial. Drive a low-poly coupe around one closed desert circuit, watch the current lap, and try to beat the best lap. The game uses procedural geometry, so there are no models or textures to download. It does need an internet connection to load the pinned Three.js module.

**Data shape and design.** The track is an ellipse with a centerline and a road width. The car stores its angle around the loop, its lateral offset, its speed, and its steering angle relative to the road. The timer stores the lap start, next finish crossing, and best time. This is an arcade driving model, not a free-roaming physics simulation. I chose track-relative driving because the rendered road and lap counter can share the same geometry, with no separate collision or checkpoint map to maintain.

**Throughput checkpoint**
- **Blocking first steps.** Define the road geometry and what counts as a completed lap.
- **Independent workstreams.** The scenery and HUD can change without changing the driving rules.
- **Shared mutable state.** The animation loop owns car and lap updates. Keyboard events only update input or request a reset.
- **Smallest safe decomposition.** One HTML file with separate track, driving, and display functions. No build step or asset pipeline.

**Principles applied.** *Model the domain* led to track-relative car state and explicit finish crossings. *Prove it works* led to the browser checks below. I could not run the game here, so its runtime behavior and layout remain unverified.

## `index.html`

Save the entire block as `index.html` and open it in a desktop browser with WebGL 2. If the browser blocks module loading from a local file, serve the containing folder with `python3 -m http.server 8000` and open `http://localhost:8000`.

```html
