    p { font-size: .8rem; margin: .25rem 0 0; }
    #status { color: #ffd49d; }
  </style>
</head>
<body>
  <div id="world" aria-hidden="true"></div>
  <section class="hud" aria-label="Race dashboard">
    <h1>Mesa Loop</h1>
    <dl>
      <div><dt>Current lap</dt><dd id="lap">0:00.000</dd></div>
      <div><dt>Best lap</dt><dd id="best">None yet</dd></div>
    </dl>
    <p>W / ↑ accelerate · S / ↓ brake</p>
    <p>A / ← and D / → steer · R restart</p>
    <p id="status" role="status">Loading track…</p>
  </section>
  <noscript>Enable JavaScript to play Mesa Loop.</noscript>

  <script type="module">
    const status = document.querySelector('#status');

    try {
      const T = await import('https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js');
      run(T);
    } catch (error) {
      status.textContent = 'Could not load the game. Check your connection and WebGL 2 support, then reload.';
      console.error(error);
    }

    function run(T) {
      const TAU = Math.PI * 2;
      const A = 61, B = 39, ROAD = 6;
      const clamp = T.MathUtils.clamp;
      const scene = new T.Scene();
      const sky = 0xffba8b;
      scene.background = new T.Color(sky);
      scene.fog = new T.Fog(sky, 100, 245);
      const chase = new T.PerspectiveCamera(58, 1, .1, 350);
      const overview = new T.OrthographicCamera(-80, 80, 55, -55, .1, 350);
      overview.position.set(0, 130, 0);
      overview.up.set(0, 0, -1);
      overview.lookAt(0, 0, 0);
      const reduced = matchMedia('(prefers-reduced-motion: reduce)');
      const renderer = new T.WebGLRenderer({ antialias: true });
      document.querySelector('#world').append(renderer.domElement);

      function resize() {
        const ratio = innerWidth / Math.max(1, innerHeight);
        renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
        renderer.setSize(innerWidth, innerHeight);
        chase.aspect = ratio;
        chase.updateProjectionMatrix();
        const halfHeight = Math.max(56, 76 / ratio);
        overview.top = halfHeight;
        overview.bottom = -halfHeight;
        overview.left = -halfHeight * ratio;
        overview.right = halfHeight * ratio;
        overview.updateProjectionMatrix();
      }
      addEventListener('resize', resize);
      resize();

      scene.add(new T.HemisphereLight(0xffead4, 0x995a58, 2));
      const sun = new T.DirectionalLight(0xffe0ad, 2.1);
      sun.position.set(-35, 70, -25);
      scene.add(sun);

      function mesh(parent, geometry, color) {
        const item = new T.Mesh(
          geometry,
          new T.MeshStandardMaterial({ color, flatShading: true, side: T.DoubleSide })
        );
        parent.add(item);
        return item;
      }

      function box(parent, color, w, h, d, x, y, z) {
        const item = mesh(parent, new T.BoxGeometry(w, h, d), color);
        item.position.set(x, y, z);
        return item;
      }

      function roadFrame(angle) {
        const s = Math.sin(angle), c = Math.cos(angle);
        const length = Math.hypot(A * s, B * c);
        const tx = -A * s / length, tz = B * c / length;
        return { x: A * c, z: B * s, tx, tz, nx: tz, nz: -tx, length };
      }

      function strip(start, end, inner, outer, y, color, segments) {
        const vertices = [], indices = [];
        for (let i = 0; i <= segments; i++) {
          const f = roadFrame(start + (end - start) * i / segments);
          for (const d of [inner, outer]) {
            vertices.push(f.x + d * f.nx, y, f.z + d * f.nz);
          }
          if (i > 0) {
            const k = 2 * (i - 1);
            indices.push(k, k + 2, k + 1, k + 1, k + 2, k + 3);
          }
        }
        const geo = new T.BufferGeometry();
        geo.setAttribute('position', new T.Float32BufferAttribute(vertices, 3));
        geo.setIndex(indices);
        geo.computeVertexNormals();
        mesh(scene, geo, color);
      }

      box(scene, 0xcb7853, 700, .3, 700, 0, -.18, 0);
      strip(0, TAU, -8, 8, .01, 0xa6533e, 160);
      strip(0, TAU, -ROAD, ROAD, .04, 0x383747, 160);
      for (let i = 0; i < 80; i++) {
        const a = TAU * i / 80, b = TAU * (i + 1) / 80;
        const tint = i % 2 ? 0xffebcd : 0xf97662;
        strip(a, b, -6, -5.45, .06, tint, 2);
        strip(a, b, 5.45, 6, .06, tint, 2);
        if (i % 2 === 0) strip(a, a + .035, -.1, .1, .065, 0xd4bd9c, 2);
      }
      for (let row = 0; row < 2; row++) {
        for (let i = 0; i < 12; i++) {
          strip((row - 1) * .019, row * .019, i - 6, i - 5, .075,
            (row + i) % 2 ? 0x25232c : 0xfff4df, 2);
        }
      }

      let seed = 89;
      function random() {
        seed = (Math.imul(1664525, seed) + 1013904223) >>> 0;
        return seed / 4294967296;
      }
      for (let i = 0; i < 65; i++) {
        const a = random() * TAU;
        const d = i < 25 ? -12 - random() * 13 : 12 + random() * 39;
        const f = roadFrame(a);
        const h = 1.3 + random() * (i < 25 ? 2 : 8);
        const rock = mesh(scene,
          new T.CylinderGeometry(h * .39, h * .72, h, 5),
          i % 2 ? 0x9f4c42 : 0xb56044);
        rock.position.set(f.x + d * f.nx, h / 2, f.z + d * f.nz);
        rock.rotation.y = random() * TAU;
      }

      const car = new T.Group();
      scene.add(car);
      box(car, 0xffca46, 2, .65, 3.8, 0, .69, 0);
      box(car, 0x204153, 1.55, .6, 1.75, 0, 1.25, -.23);
      box(car, 0xffe9ab, .22, .025, 1.15, 0, 1.03, 1.26);
      for (const x of [-1, 1]) {
        for (const z of [-1.17, 1.17]) {
          const wheel = mesh(car, new T.CylinderGeometry(.42, .42, .34, 8), 0x211f29);
          wheel.position.set(x, .46, z);
          wheel.rotation.z = Math.PI / 2;
        }
        box(car, 0xff4938, .4, .16, .08, x * .69, .76, -1.92);
      }

      const lapNode = document.querySelector('#lap');
      const bestNode = document.querySelector('#best');
      const storageKey = 'mesa-loop.best.v1';
      let best = Infinity;
      try {
        const saved = Number(localStorage.getItem(storageKey));
        if (Number.isFinite(saved) && saved > 0) best = saved;
      } catch {}

      function format(seconds) {
        const ms = Math.floor(seconds * 1000);
        return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60).padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
      }

      bestNode.textContent = Number.isFinite(best) ? format(best) : 'None yet';
      const pressed = new Set();
      const controls = new Set(['KeyW', 'ArrowUp', 'KeyS', 'ArrowDown',
        'KeyA', 'ArrowLeft', 'KeyD', 'ArrowRight', 'KeyR']);
      const down = (...codes) => codes.some(code => pressed.has(code));
      let state, clock = 0, resetRequested = false, accumulator = 0;

      function reset() {
        state = { angle: 0, offset: 0, speed: 0, steer: 0, start: null, finish: TAU };
        clock = 0;
        status.textContent = 'Accelerate to start the timer.';
      }

      addEventListener('keydown', event => {
        if (!controls.has(event.code) || event.ctrlKey || event.metaKey || event.altKey) return;
        event.preventDefault();
        pressed.add(event.code);
        if (event.code === 'KeyR' && !event.repeat) resetRequested = true;
      });
      addEventListener('keyup', event => pressed.delete(event.code));
      addEventListener('blur', () => { pressed.clear(); accumulator = 0; });
      document.addEventListener('visibilitychange', () => {
        pressed.clear();
        accumulator = 0;
        previous = performance.now();
      });

      function step(dt) {
        const throttle = down('KeyW', 'ArrowUp');
        const brake = down('KeyS', 'ArrowDown');
        const turn = Number(down('KeyD', 'ArrowRight')) - Number(down('KeyA', 'ArrowLeft'));
        const gravel = Math.abs(state.offset) > ROAD - .55;
        const drive = brake ? -46 : throttle ? 19 : -7;
        const limit = gravel ? 13 : 42;

        state.speed = clamp(state.speed + drive * dt, 0, 42);
        if (state.speed > limit) state.speed = Math.max(limit, state.speed - 36 * dt);
        if (state.start === null && state.speed > 0) {
          state.start = clock;
          status.textContent = 'Lap in progress.';
        }

        state.steer += (turn * .74 - state.steer) * (1 - Math.exp(-9 * dt));
        const f = roadFrame(state.angle);
        const oldAngle = state.angle;
        const curvature = A * B / f.length ** 3;
        state.angle += state.speed * Math.cos(state.steer) * dt /
          (f.length * (1 + curvature * state.offset));
        const offset = state.offset + state.speed * Math.sin(state.steer) * dt;
        state.offset = clamp(offset, -8, 8);
        if (offset !== state.offset) state.speed *= Math.exp(-3 * dt);

        if (state.angle >= state.finish) {
          const fraction = (state.finish - oldAngle) / (state.angle - oldAngle);
          const crossing = clock + dt * fraction;
          const time = crossing - state.start;
          if (time < best) {
            best = time;
            bestNode.textContent = format(best);
            try { localStorage.setItem(storageKey, String(best)); } catch {}
            status.textContent = `New best. Last lap ${format(time)}.`;
          } else {
            status.textContent = `Last lap ${format(time)}.`;
          }
          state.start = crossing;
          state.finish += TAU;
        }
        clock += dt;
      }

      function draw() {
        const f = roadFrame(state.angle);
        car.position.set(f.x + f.nx * state.offset, .05, f.z + f.nz * state.offset);
        car.rotation.y = Math.atan2(f.tx, f.tz) + state.steer;
        chase.position.set(car.position.x - 11 * f.tx, 6.4, car.position.z - 11 * f.tz);
        chase.lookAt(car.position.x + 5 * f.tx, 1, car.position.z + 5 * f.tz);
        lapNode.textContent = format(state.start === null ? 0 : clock - state.start);
        renderer.render(scene, reduced.matches ? overview : chase);
      }

      const tick = 1 / 120;
      let previous = performance.now();
      reset();
      renderer.setAnimationLoop(now => {
        if (resetRequested) {
          reset();
          resetRequested = false;
        }
        if (!document.hidden) {
          accumulator += clamp((now - previous) / 1000, 0, .1);
          while (accumulator >= tick) {
            step(tick);
            accumulator -= tick;
          }
          draw();
        }
        previous = now;
      });
    }
  </script>
</body>
</html>
