    header { top: 12px; left: 12px; right: 12px; width: fit-content; }
    h1 { margin: 0 0 .5rem; font-size: 1.2rem; color: #afffcd; }
    dl { display: flex; flex-wrap: wrap; gap: .5rem 1.3rem; margin: 0; }
    dt { font-size: .75rem; color: #c1dad0; }
    dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; }
    footer { bottom: 12px; left: 12px; right: 12px; width: fit-content; }
    #status { margin: 0 0 .25rem; color: #afffcd; }
    small { color: #e1eee8; }
  </style>
</head>
<body>
  <header class="panel">
    <h1>Mint Circuit</h1>
    <dl>
      <div><dt>Current lap</dt><dd id="lap">--:--.---</dd></div>
      <div><dt>Best lap</dt><dd id="best">--:--.---</dd></div>
      <div><dt>Speed</dt><dd id="speed">0 km/h</dd></div>
    </dl>
  </header>
  <footer class="panel">
    <p id="status" role="status">Loading the track…</p>
    <small>W / ↑ accelerate · S / ↓ brake or reverse · A D / ← → steer · R restart</small>
  </footer>

  <script type="module">
    const status = document.querySelector('#status');

    try {
      const THREE = await import(
        'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js'
      );
      start(THREE);
    } catch (error) {
      status.textContent = 'Could not start. Check your internet connection and WebGL support.';
      console.error(error);
    }

    function start(T) {
      const lapDisplay = document.querySelector('#lap');
      const bestDisplay = document.querySelector('#best');
      const speedDisplay = document.querySelector('#speed');
      const storageKey = 'mint-circuit.best.v1';
      const emptyTime = '--:--.---';

      function readBest() {
        try {
          const seconds = Number(localStorage.getItem(storageKey));
          return Number.isFinite(seconds) && seconds > 0 ? seconds : null;
        } catch {
          return null;
        }
      }

      function formatTime(seconds) {
        if (seconds === null) return emptyTime;
        const ms = Math.floor(seconds * 1000);
        const pad = (value, length) => String(value).padStart(length, '0');
        return `${pad(Math.floor(ms / 60000), 2)}:${pad(Math.floor(ms / 1000) % 60, 2)}.${pad(ms % 1000, 3)}`;
      }

      const scene = new T.Scene();
      scene.background = new T.Color(0xb7e9df);
      scene.fog = new T.Fog(0xb7e9df, 85, 190);
      const camera = new T.PerspectiveCamera(60, 1, .1, 240);
      const renderer = new T.WebGLRenderer({ antialias: true });
      renderer.domElement.setAttribute('aria-label', 'Chase camera view of Mint Circuit');
      document.body.append(renderer.domElement);

      scene.add(new T.HemisphereLight(0xfff5d7, 0x47745c, 2));
      const sun = new T.DirectionalLight(0xffeed0, 2.2);
      sun.position.set(-25, 45, 15);
      scene.add(sun);

      const path = new T.CatmullRomCurve3(
        [[-43, 13], [-39, -18], [-12, -31], [16, -24],
         [43, -26], [48, 1], [29, 24], [-8, 32]]
          .map(([x, z]) => new T.Vector3(x, 0, z)),
        true
      );
      path.arcLengthDivisions = 1600;
      const track = { path, length: path.getLength(), halfWidth: 5.8 };

      function sample(distance) {
        const u = T.MathUtils.euclideanModulo(distance, track.length) / track.length;
        const point = track.path.getPointAt(u);
        const forward = track.path.getTangentAt(u);
        const right = new T.Vector3(-forward.z, 0, forward.x);
        return { point, forward, right };
      }

      function material(color) {
        return new T.MeshStandardMaterial({ color, flatShading: true });
      }

      function box(parent, mat, w, h, d, x, y, z) {
        const mesh = new T.Mesh(new T.BoxGeometry(w, h, d), mat);
        mesh.position.set(x, y, z);
        parent.add(mesh);
        return mesh;
      }

      function strip(left, right, color, y) {
        const positions = [];
        const indices = [];
        const segments = 240;
        for (let i = 0; i <= segments; i++) {
          const f = sample(i * track.length / segments);
          for (const offset of [left, right]) {
            const p = f.point.clone().addScaledVector(f.right, offset);
            positions.push(p.x, y, p.z);
          }
          if (i < segments) {
            const a = i * 2;
            indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
          }
        }
        const geometry = new T.BufferGeometry();
        geometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
        geometry.setIndex(indices);
        geometry.computeVertexNormals();
        const mat = material(color);
        mat.side = T.DoubleSide;
        scene.add(new T.Mesh(geometry, mat));
      }

      box(scene, material(0x548d68), 340, .4, 340, 0, -.24, 0);
      strip(-6.4, 6.4, 0xf1b878, 0);
      strip(-track.halfWidth, track.halfWidth, 0x304750, .02);
      strip(-5.55, -5.43, 0xd7fff1, .035);
      strip(5.43, 5.55, 0xd7fff1, .035);

      function trackTile(distance, offset, width, depth, mat) {
        const f = sample(distance);
        const p = f.point.addScaledVector(f.right, offset);
        const tile = box(scene, mat, width, .022, depth, p.x, .045, p.z);
        tile.rotation.y = Math.atan2(-f.forward.x, -f.forward.z);
      }

      const chalk = material(0xe7fff4);
      const ink = material(0x142729);
      for (let d = 7; d < track.length - 5; d += 7) {
        trackTile(d, 0, .13, 2.5, chalk);
      }
      for (let row = 0; row < 2; row++) {
        const tileWidth = track.halfWidth * 2 / 12;
        for (let col = 0; col < 12; col++) {
          trackTile((row - .5) * .65, -track.halfWidth + (col + .5) * tileWidth,
            tileWidth, .65, (row + col) % 2 ? chalk : ink);
        }
      }

      const bark = material(0x77533c);
      const leaves = [material(0x24664f), material(0x327c56), material(0x46945f)];
      const crown = new T.ConeGeometry(1.8, 4, 5);
      for (let i = 0; i < 48; i++) {
        const f = sample(i * track.length / 48);
        const p = f.point.addScaledVector(f.right, 10 + (i * 7 % 9));
        box(scene, bark, .38, 1.6, .38, p.x, .8, p.z);
        const tree = new T.Mesh(crown, leaves[i % leaves.length]);
        tree.position.set(p.x, 2.8, p.z);
        tree.rotation.y = i;
        tree.scale.setScalar(.8 + (i % 5) * .1);
        scene.add(tree);
      }

      const car = new T.Group();
      scene.add(car);
      const paint = material(0xff704e);
      box(car, paint, 1.85, .55, 3.45, 0, .58, 0);
      box(car, material(0x193c47), 1.36, .55, 1.48, 0, 1.04, .17);
      box(car, chalk, 1.4, .08, 1.1, 0, 1.35, .17);
      for (const x of [-.96, .96]) {
        for (const z of [-1.05, 1.05]) {
          box(car, ink, .38, .66, .68, x, .34, z);
        }
      }

      const keys = new Set();
      const controls = new Set([
        'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
        'KeyW', 'KeyA', 'KeyS', 'KeyD', 'KeyR'
      ]);
      const held = (a, b) => keys.has(a) || keys.has(b);
      const race = { best: readBest() };

      function reset() {
        Object.assign(race, {
          distance: -9, offset: 0, speed: 0, clock: 0,
          lapStarted: null, nextFinish: 0
        });
        status.textContent = 'Cross the start line to begin timing.';
        pose(1);
      }

      function update(dt) {
        const accelerate = held('ArrowUp', 'KeyW');
        const brake = held('ArrowDown', 'KeyS');
        const steer = Number(held('ArrowRight', 'KeyD')) -
                      Number(held('ArrowLeft', 'KeyA'));
        const oldDistance = race.distance;
        const oldClock = race.clock;
        race.clock += dt;

        if (accelerate) race.speed += 17 * dt;
        if (brake) race.speed -= (race.speed > 0 ? 32 : 12) * dt;
        if (!accelerate && !brake) {
          race.speed = T.MathUtils.lerp(race.speed, 0, 1 - Math.exp(-1.5 * dt));
        }
        race.speed = T.MathUtils.clamp(race.speed, -9, 37);
        race.offset = T.MathUtils.clamp(
          race.offset + steer * race.speed * .28 * dt, -4.8, 4.8
        );
        if (Math.abs(race.offset) > 4.45) race.speed *= Math.exp(-2.2 * dt);
        race.distance += race.speed * dt;

        if (oldDistance < race.nextFinish && race.distance >= race.nextFinish) {
          const fraction = (race.nextFinish - oldDistance) / (race.distance - oldDistance);
          const crossedAt = oldClock + fraction * dt;

          if (race.lapStarted === null) {
            status.textContent = 'Lap started.';
          } else {
            const lap = crossedAt - race.lapStarted;
            if (race.best === null || lap < race.best) {
              race.best = lap;
              try { localStorage.setItem(storageKey, String(lap)); } catch {}
              status.textContent = `New best lap: ${formatTime(lap)}`;
            } else {
              status.textContent = `Last lap: ${formatTime(lap)}`;
            }
          }
          race.lapStarted = crossedAt;
          race.nextFinish += track.length;
        }
      }

      function pose(blend) {
        const f = sample(race.distance);
        car.position.copy(f.point).addScaledVector(f.right, race.offset);
        car.rotation.y = Math.atan2(-f.forward.x, -f.forward.z);
        const eye = car.position.clone().addScaledVector(f.forward, -9);
        eye.y = 5.4;
        camera.position.lerp(eye, blend);
        const target = sample(race.distance + 11).point;
        target.y = 1;
        camera.lookAt(target);
      }

      function resize() {
        camera.aspect = innerWidth / innerHeight;
        camera.updateProjectionMatrix();
        renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
        renderer.setSize(innerWidth, innerHeight);
      }

      addEventListener('resize', resize);
      addEventListener('keydown', event => {
        if (!controls.has(event.code)) return;
        event.preventDefault();
        keys.add(event.code);
        if (event.code === 'KeyR' && !event.repeat) reset();
      });
      addEventListener('keyup', event => keys.delete(event.code));
      addEventListener('blur', () => keys.clear());
      document.addEventListener('visibilitychange', () => {
        keys.clear();
        previous = null;
      });

      let previous = null;
      function frame(now) {
        const dt = previous === null ? 0 : Math.min((now - previous) / 1000, .05);
        previous = now;
        if (!document.hidden) {
          update(dt);
          pose(1 - Math.exp(-9 * dt));
          lapDisplay.textContent = formatTime(
            race.lapStarted === null ? null : race.clock - race.lapStarted
          );
          bestDisplay.textContent = formatTime(race.best);
          speedDisplay.textContent = `${Math.round(Math.abs(race.speed) * 3.6)} km/h`;
          renderer.render(scene, camera);
        }
        requestAnimationFrame(frame);
      }

      resize();
      reset();
      requestAnimationFrame(frame);
    }
  </script>
</body>
</html>
```

### How I would verify it

**Prove it works.** I would test the actual game in a browser. The behaviors below are inferred from the code, not measured. I did not run the game here.

1. **Load the scene.** Open `index.html` in a desktop browser. If the browser blocks the CDN import from a local file, serve the folder with `python -m http.server 8000` and open `http://localhost:8000/`. Expect a visible car, track, and HUD with no console errors.
2. **Drive a lap.** Use both key sets. Expect acceleration, braking, reverse, and lateral steering. The timer should start at the first forward crossing. The next full circuit should set a best time and start a new lap.
3. **Try to fool the timer.** Reverse back over the line, then drive forward over it again. Expect neither a new lap nor a change to the best time. Drive against the road edge and confirm the car slows without leaving the track.
4. **Check restart and persistence.** Complete two laps. Expect the best display to keep the faster time. Press R, then reload at the same HTTP address. The current lap should reset both times, and the best should survive if browser storage is enabled.
5. **Check focus and layout.** Hold accelerate, switch tabs, release it, then return. Expect no stuck throttle and no hidden-tab time added. Resize to a narrow window and check that the timer and controls remain readable.

Save this as `index.html` and open it in a desktop browser with internet access. **Switchback** is a low-poly time trial with one closed circuit, keyboard steering, a live lap timer, and a best lap saved in the browser when storage is available. No build step is required. I haven't run it here.

**Data shape and design.** The track is a closed spline. The car has a distance along that spline, a lateral offset, and a speed. The race clock has an elapsed time and an optional best time. I chose track-relative steering over free-roaming physics so you can pick a line through corners and run onto the grass, but you can't skip a section to set a faster lap. The tradeoff is that you can't turn around or drive across the infield.

**Throughput checkpoint**

- **Blocking first steps.** Define track coordinates and the start/finish rule before wiring the car and HUD.
- **Independent workstreams.** Scenery and HUD layout do not own race state. No parallel workers were available.
- **Shared mutable state.** The game loop owns the car and clock. The HUD reads them.
- **Smallest safe decomposition.** One HTML file with separate track, simulation, and rendering functions. No open product decisions.

