    </dl>
  </header>
  <div id="view"><p>Loading the track…</p></div>
  <footer>
    <p>Drive with WASD or arrow keys. Press R to restart.</p>
    <button id="restart" type="button" disabled>Restart lap</button>
  </footer>
  <p id="status" role="status"></p>
</main>

<script type="module">
const view = document.querySelector("#view");
try {
  const THREE = await import("https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js");
  start(THREE);
} catch (error) {
  console.error(error);
  const message = document.createElement("p");
  message.textContent = "Could not load the game. Check your internet connection and WebGL support, then reload.";
  view.replaceChildren(message);
}

function start(T) {
  const ui = Object.fromEntries(
    ["current", "best", "speed", "restart", "status"].map(id => [id, document.getElementById(id)])
  );
  const scene = new T.Scene();
  scene.background = new T.Color(0x9dd5cd);
  const renderer = new T.WebGLRenderer({ antialias: true });
  renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
  renderer.domElement.setAttribute("role", "img");
  renderer.domElement.setAttribute("aria-label", "3D view of the Switchback race track");
  view.replaceChildren(renderer.domElement);

  const camera = new T.PerspectiveCamera(57, 1, 0.1, 450);
  const overhead = new T.OrthographicCamera(-90, 90, 85, -85, 0.1, 450);
  overhead.position.set(0, 160, 0);
  overhead.up.set(0, 0, -1);
  overhead.lookAt(0, 0, 0);
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");

  scene.add(new T.HemisphereLight(0xfff6df, 0x5b716b, 2));
  const sun = new T.DirectionalLight(0xffecc5, 2);
  sun.position.set(-30, 50, 12);
  scene.add(sun);

  function mesh(geometry, color, parent = scene, basic = false) {
    const material = basic
      ? new T.MeshBasicMaterial({ color, side: T.DoubleSide })
      : new T.MeshStandardMaterial({ color, flatShading: true });
    const object = new T.Mesh(geometry, material);
    parent.add(object);
    return object;
  }

  function box(parent, color, w, h, d, x, y, z, basic = false) {
    const object = mesh(new T.BoxGeometry(w, h, d), color, parent, basic);
    object.position.set(x, y, z);
    return object;
  }

  box(scene, 0x619967, 650, 0.4, 650, 0, -0.22, 0);
  const route = new T.CatmullRomCurve3([
    [-28, 42], [13, 46], [47, 31], [51, 4], [27, -12],
    [32, -37], [4, -52], [-37, -46], [-52, -17], [-45, 16]
  ].map(([x, z]) => new T.Vector3(x, 0, z)), true);
  route.arcLengthDivisions = 1500;
  const length = route.getLength();
  const halfRoad = 5.5;
  const segments = 320;
  const clamp = T.MathUtils.clamp;

  function sample(u) {
    const point = route.getPointAt(u);
    const forward = route.getTangentAt(u);
    const right = new T.Vector3(-forward.z, 0, forward.x);
    return { point, forward, right };
  }

  function strip(left, right, height, color, start = 0, end = segments) {
    const vertices = [], indices = [];
    for (let i = start; i <= end; i++) {
      const frame = sample(i / segments);
      for (const offset of [left, right]) {
        const p = frame.point.clone().addScaledVector(frame.right, offset);
        vertices.push(p.x, height, p.z);
      }
      const n = (i - start) * 2;
      if (n > 0) indices.push(n - 2, n - 1, n, n, n - 1, n + 1);
    }
    const geometry = new T.BufferGeometry();
    geometry.setAttribute("position", new T.Float32BufferAttribute(vertices, 3));
    geometry.setIndex(indices);
    mesh(geometry, color, scene, true);
  }

  strip(-6, 6, 0.01, 0xeee1b7);
  strip(-halfRoad, halfRoad, 0.025, 0x343d4d);
  for (let i = 0; i < segments; i += 8) {
    strip(-0.07, 0.07, 0.035, 0xb8bec5, i, i + 3);
  }
  for (let i = 0; i < segments; i += 4) {
    const color = i % 8 === 0 ? 0xe35549 : 0xffecd5;
    strip(-6, -5.5, 0.04, color, i, i + 4);
    strip(5.5, 6, 0.04, color, i, i + 4);
  }

  const startLine = new T.Group();
  const grid = sample(0);
  startLine.position.copy(grid.point);
  startLine.rotation.y = Math.atan2(grid.forward.x, grid.forward.z);
  scene.add(startLine);
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 10; col++) {
      box(startLine, (col + row) % 2 ? 0x202632 : 0xfff7e6,
        1.1, 0.02, 0.55, col * 1.1 - 4.95, 0.05, (row - 0.5) * 0.55, true);
    }
  }

  for (let i = 0; i < 64; i++) {
    const frame = sample(i / 64);
    const side = i % 3 === 0 ? -1 : 1;
    const p = frame.point.addScaledVector(frame.right, side * (12 + (i * 7 % 8)));
    box(scene, 0x795637, 0.45, 1.8, 0.45, p.x, 0.9, p.z);
    const crown = mesh(new T.ConeGeometry(1.4 + (i % 4) * 0.26, 3.6, 5),
      i % 2 ? 0x287554 : 0x388454);
    crown.position.set(p.x, 2.65, p.z);
    crown.rotation.y = i;
  }

  const car = new T.Group();
  scene.add(car);
  box(car, 0xffbe43, 1.75, 0.55, 3.1, 0, 0.58, 0);
  box(car, 0x203649, 1.35, 0.55, 1.38, 0, 1.02, -0.23);
  box(car, 0xffdc7d, 1.74, 0.14, 0.32, 0, 1.08, -1.41);
  for (const x of [-0.82, 0.82]) {
    for (const z of [-1, 1]) {
      const wheel = mesh(new T.CylinderGeometry(0.35, 0.35, 0.34, 10), 0x19222b, car);
      wheel.rotation.z = Math.PI / 2;
      wheel.position.set(x, 0.37, z);
    }
    box(car, 0xff4545, 0.33, 0.17, 0.05, x * 0.78, 0.65, -1.56, true);
  }

  const key = "switchback.best.v1";
  function readBest() {
    try {
      const value = Number(localStorage.getItem(key));
      return Number.isFinite(value) && value > 0 ? value : null;
    } catch {
      return null;
    }
  }

  const state = { distance: 0, lane: 0, speed: 0, elapsed: 0, best: readBest() };
  const controls = new Set();
  const drivingKeys = new Set([
    "KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowLeft", "ArrowDown", "ArrowRight"
  ]);
  const held = (...codes) => codes.some(code => controls.has(code));

  function reset() {
    Object.assign(state, { distance: 0, lane: 0, speed: 0, elapsed: 0 });
    controls.clear();
    ui.status.textContent = "Accelerate to start your lap.";
  }

  addEventListener("keydown", event => {
    if (event.altKey || event.ctrlKey || event.metaKey) return;
    if (drivingKeys.has(event.code)) {
      event.preventDefault();
      controls.add(event.code);
    } else if (event.code === "KeyR" && !event.repeat) {
      reset();
    }
  });
  addEventListener("keyup", event => controls.delete(event.code));
  let previousTime;
  function releaseControls() {
    controls.clear();
    previousTime = undefined;
  }
  addEventListener("blur", releaseControls);
  document.addEventListener("visibilitychange", releaseControls);
  ui.restart.addEventListener("click", reset);

  function step(dt) {
    const gas = held("KeyW", "ArrowUp");
    const brake = held("KeyS", "ArrowDown");
    const steer = Number(held("KeyD", "ArrowRight")) - Number(held("KeyA", "ArrowLeft"));
    const grass = Math.abs(state.lane) > halfRoad - 0.7;
    const limit = grass ? 12 : 43;
    const acceleration = brake ? -42 : state.speed > limit ? -36 : gas ? 17 : -7;
    const maxSpeed = Math.max(limit, state.speed);
    state.speed = clamp(state.speed + acceleration * dt, 0, maxSpeed);
    state.lane = clamp(state.lane + steer * Math.min(10, state.speed * 0.42) * dt, -9, 9);

    const travel = state.speed * dt;
    if (travel === 0 && state.distance === 0) return;
    if (state.distance + travel >= length) {
      const fraction = (length - state.distance) / travel;
      const lap = state.elapsed + dt * fraction;
      const newBest = state.best === null || lap < state.best;
      if (newBest) {
        state.best = lap;
        try { localStorage.setItem(key, String(lap)); } catch {}
      }
      ui.status.textContent = `${newBest ? "New best" : "Lap complete"}: ${format(lap)}`;
      state.distance += travel - length;
      state.elapsed = dt * (1 - fraction);
    } else {
      if (state.elapsed === 0 && state.distance === 0) {
        ui.status.textContent = "Lap in progress.";
      }
      state.distance += travel;
      state.elapsed += dt;
    }
  }

  function format(seconds) {
    const ms = Math.floor(seconds * 1000);
    const pad = (n, width) => String(n).padStart(width, "0");
    return `${Math.floor(ms / 60000)}:${pad(Math.floor(ms / 1000) % 60, 2)}.${pad(ms % 1000, 3)}`;
  }

  function resize() {
    const width = view.clientWidth;
    const height = view.clientHeight;
    if (!width || !height) return;
    renderer.setSize(width, height);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    const halfHeight = Math.max(76, 76 / camera.aspect);
    overhead.left = -halfHeight * camera.aspect;
    overhead.right = -overhead.left;
    overhead.top = halfHeight;
    overhead.bottom = -halfHeight;
    overhead.updateProjectionMatrix();
  }
  new ResizeObserver(resize).observe(view);
  resize();

  function frame(now) {
    const dt = previousTime === undefined ? 0 : Math.min((now - previousTime) / 1000, 0.1);
    previousTime = now;
    if (document.hasFocus() && !document.hidden) {
      const steps = Math.max(1, Math.ceil(dt / 0.01));
      for (let i = 0; i < steps; i++) step(dt / steps);
    }
    const pose = sample(state.distance / length);
    car.position.copy(pose.point).addScaledVector(pose.right, state.lane);
    car.rotation.y = Math.atan2(pose.forward.x, pose.forward.z);
    if (!reducedMotion.matches) {
      camera.position.copy(car.position).addScaledVector(pose.forward, -10);
      camera.position.y = 6.5;
      const target = car.position.clone().addScaledVector(pose.forward, 7);
      target.y = 0.7;
      camera.lookAt(target);
    }
    ui.current.textContent = format(state.elapsed);
    ui.best.textContent = state.best === null ? "Not set" : format(state.best);
    ui.speed.textContent = `${Math.round(state.speed * 3.6)} km/h`;
    renderer.render(scene, reducedMotion.matches ? overhead : camera);
    requestAnimationFrame(frame);
  }

  reset();
  ui.restart.disabled = false;
  requestAnimationFrame(frame);
}
</script>
</body>
</html>
```

### How I'd verify it

These are expected results from reading the code, not measured browser results.

| Browser check | Expected result |
|---|---|
| Open the file with DevTools visible. | The track and car render, the timer shows `0:00.000`, and the console has no errors. |
| Drive with WASD, then repeat with the arrow keys. Steer onto the grass and brake. | Both key sets work, the grass slows the car, and braking stops it without reversing. |
| Complete a lap, then complete a deliberately slower one. | The first crossing records a best and starts the next timer. The slower lap does not replace the best. |
| Press R mid-lap, then reload after setting a best. | Restart clears the current lap, not the best. Reload preserves the best if the browser permits storage for that URL. |
| Hold accelerate, switch tabs, release the key, then return. | The game does not advance while unfocused, and acceleration does not get stuck. |
| Test at 320px wide and at 200% zoom. Enable reduced motion. | HUD values and controls remain readable. Reduced motion uses a fixed overhead camera instead of the chase camera. |
| Block the CDN request and reload. | The loading message changes to an error with recovery instructions. |

**Principles applied.** *Model the domain* led to track-relative coordinates and a single owner for lap state. *Prove it works* led to checks against the actual browser game, especially lap rollover and best-lap persistence, rather than treating a source review as a pass.

Save this as `index.html`. It gives players a low-poly time trial on one closed track, with keyboard steering, a live lap timer, and a best lap saved in the browser. The whole game is in one file. Three.js is the only external dependency.

**Controls:** W or ↑ to accelerate, S or ↓ to brake and reverse, A/D or ←/→ to steer, and R to restart without clearing the best lap.

**Design and throughput checkpoint**

| Checkpoint | Decision |
|---|---|
| Blocking first steps | **Model the domain.** The track is an oval with a half-width. The car has an unwrapped angle, a lateral offset, and two velocities. The lap clock holds the current start time, the next finish angle, and the best time. |
| Independent workstreams | N/A. The renderer and driving code share one track model in one file. |
| Shared mutable state | The frame loop owns driving and lap updates. Rendering reads the result. Input handlers record key state or request a restart. |
| Smallest safe decomposition | One file, with separate functions for track geometry, driving, lap timing, and rendering. **Prove it works** sets the verification target at actual browser play. I could not run that check here. |

The key tradeoff is track-relative steering instead of free-roaming physics. I chose it for this small arcade racer because it keeps the car on the circuit and lets the lap logic require one full revolution of net forward travel without separate checkpoints. There are no open setup decisions beyond the port you want to serve it on.

