    h1 { margin: 0 0 8px; font-size: 19px; letter-spacing: .08em; }
    dl { margin: 0; display: grid; grid-template-columns: auto auto; gap: 4px 20px; }
    dt { color: #ffd6b7; }
    dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; }
    #controls { bottom: 14px; left: 14px; right: 14px; width: fit-content; }
    #notice { margin: 8px 0 0; color: #ffe29a; min-height: 1.4em; }
  </style>
</head>
<body>
  <header id="hud">
    <h1>SUNSET CIRCUIT</h1>
    <dl>
      <dt>Lap</dt><dd id="lap">1</dd>
      <dt>Time</dt><dd id="time">0:00.000</dd>
      <dt>Best</dt><dd id="best">--:--.---</dd>
      <dt>Speed</dt><dd id="speed">0 km/h</dd>
    </dl>
    <p id="notice" role="status">Accelerate to start</p>
  </header>
  <div id="controls">W / ↑ Accelerate · S / ↓ Brake / Reverse · A D / ← → Steer · R Restart</div>

  <script type="module">
    import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js";

    const TAU = Math.PI * 2;
    const A = 54, B = 36, HALF = 6, SEGMENTS = 160;
    const KEY = "sunset-circuit.best.v1";
    const clamp = THREE.MathUtils.clamp;
    const ui = Object.fromEntries(
      ["lap", "time", "best", "speed", "notice"].map(id => [id, document.getElementById(id)])
    );

    function readBest() {
      try {
        const value = Number(localStorage.getItem(KEY));
        return Number.isFinite(value) && value > 0 ? value : null;
      } catch {
        return null;
      }
    }

    const car = { angle: 0, offset: 0, speed: 0, lateral: 0 };
    const lap = { number: 1, started: null, finish: TAU, best: readBest() };
    const keys = new Set();
    let restartRequested = false;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xefb695);
    scene.fog = new THREE.Fog(0xefb695, 75, 185);
    const camera = new THREE.PerspectiveCamera(58, 1, 0.1, 230);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    document.body.prepend(renderer.domElement);
    scene.add(new THREE.HemisphereLight(0xffe8d0, 0x73617d, 2.1));
    const sun = new THREE.DirectionalLight(0xffdfad, 2.3);
    sun.position.set(-35, 60, -20);
    scene.add(sun);

    function point(angle, offset = 0, y = 0) {
      return new THREE.Vector3(
        (A + offset) * Math.cos(angle), y, (B + offset) * Math.sin(angle)
      );
    }

    function mesh(geometry, color, parent = scene) {
      const object = new THREE.Mesh(geometry, new THREE.MeshStandardMaterial({
        color, flatShading: true, side: THREE.DoubleSide
      }));
      parent.add(object);
      return object;
    }

    function box(w, h, d, color, x, y, z, parent = scene) {
      const object = mesh(new THREE.BoxGeometry(w, h, d), color, parent);
      object.position.set(x, y, z);
      return object;
    }

    function strip(lo, hi, y, color, first = 0, last = SEGMENTS) {
      const positions = [];
      for (let i = first; i < last; i++) {
        const a = i * TAU / SEGMENTS;
        const b = (i + 1) * TAU / SEGMENTS;
        const p = point(a, lo, y), q = point(a, hi, y);
        const r = point(b, lo, y), s = point(b, hi, y);
        for (const v of [p, r, q, q, r, s]) positions.push(v.x, v.y, v.z);
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
      geo.computeVertexNormals();
      mesh(geo, color);
    }

    box(390, 1, 390, 0xb78258, 0, -0.56, 0);
    strip(-HALF, HALF, 0, 0x343846);
    for (let i = 0; i < SEGMENTS; i += 2) {
      const curb = i % 4 ? 0xffe8ce : 0xc83d49;
      strip(-HALF - 0.45, -HALF, 0.03, curb, i, i + 2);
      strip(HALF, HALF + 0.45, 0.03, curb, i, i + 2);
    }
    for (let i = 4; i < SEGMENTS - 3; i += 5) {
      strip(-0.07, 0.07, 0.015, 0xe8dcc3, i, i + 2);
    }
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 12; col++) {
        box(1, 0.02, 0.42, (row + col) % 2 ? 0xfff7e9 : 0x161924,
          A - HALF + col + 0.5, 0.02, (row - 0.5) * 0.42);
      }
    }

    for (let i = 0; i < 56; i++) {
      const angle = i * 2.399963;
      const offset = i % 3 ? 12 + (i * 7 % 23) : -11 - (i * 5 % 10);
      const p = point(angle, offset);
      const height = 2 + (i * 13 % 11) * 0.42;
      const rock = mesh(new THREE.DodecahedronGeometry(1),
        [0xc97555, 0x915d61, 0xe39b68][i % 3]);
      rock.position.set(p.x, height * 0.3, p.z);
      rock.rotation.y = angle;
      rock.scale.set(height * 0.65, height * 0.65, height * 0.48);
    }

    const model = new THREE.Group();
    scene.add(model);
    box(1.85, 0.48, 3.3, 0xff584f, 0, 0.63, 0, model);
    box(1.3, 0.49, 1.38, 0x283e55, 0, 1.08, -0.25, model);
    box(1.24, 0.12, 1.08, 0xff7764, 0, 1.35, -0.3, model);
    for (const x of [-0.89, 0.89]) {
      for (const z of [-1.05, 1.05]) {
        const wheel = mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.32, 10), 0x171923, model);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(x, 0.34, z);
      }
      box(0.34, 0.14, 0.06, 0xffcf8b, x * 0.82, 0.68, 1.66, model);
      box(0.34, 0.14, 0.06, 0xff243d, x * 0.82, 0.68, -1.66, model);
    }

    const controls = new Set([
      "KeyW", "KeyA", "KeyS", "KeyD", "ArrowUp", "ArrowLeft",
      "ArrowDown", "ArrowRight", "KeyR"
    ]);
    addEventListener("keydown", event => {
      if (!controls.has(event.code)) return;
      event.preventDefault();
      if (event.code === "KeyR" && !event.repeat) restartRequested = true;
      keys.add(event.code);
    });
    addEventListener("keyup", event => keys.delete(event.code));
    addEventListener("blur", () => keys.clear());
    document.addEventListener("visibilitychange", () => keys.clear());
    const down = (a, b) => keys.has(a) || keys.has(b);

    function reset() {
      Object.assign(car, { angle: 0, offset: 0, speed: 0, lateral: 0 });
      Object.assign(lap, { number: 1, started: null, finish: TAU });
      ui.notice.textContent = "Accelerate to start";
    }

    function drive(dt) {
      const gas = down("KeyW", "ArrowUp");
      const brake = down("KeyS", "ArrowDown");
      const steer = Number(down("KeyA", "ArrowLeft")) -
        Number(down("KeyD", "ArrowRight"));
      const acceleration = gas === brake ? 0 :
        gas ? (car.speed < 0 ? 38 : 16) : (car.speed > 0 ? -34 : -9);
      car.speed = clamp(car.speed + acceleration * dt, -8, 33);
      car.speed *= Math.exp(-(acceleration ? 0.18 : 0.92) * dt);
      if (Math.abs(car.speed) < 0.04 && !acceleration) car.speed = 0;

      const target = steer * Math.sign(car.speed) * Math.min(Math.abs(car.speed) * 0.65, 8);
      car.lateral += (target - car.lateral) * (1 - Math.exp(-10 * dt));
      const offset = car.offset + car.lateral * dt;
      const limit = HALF - 1.12;
      car.offset = clamp(offset, -limit, limit);
      if (offset !== car.offset) {
        car.lateral = 0;
        car.speed *= Math.exp(-2.4 * dt);
      }

      const metresPerRadian = Math.hypot(
        (A + car.offset) * Math.sin(car.angle),
        (B + car.offset) * Math.cos(car.angle)
      );
      car.angle += car.speed * dt / metresPerRadian;
    }

    function format(seconds) {
      const ms = Math.max(0, Math.floor(seconds * 1000));
      return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60).padStart(2, "0")}.${String(ms % 1000).padStart(3, "0")}`;
    }

    function updateLap(before, frameStart, now) {
      if (lap.started === null && car.angle !== before) {
        lap.started = frameStart;
        ui.notice.textContent = "Lap in progress";
      }
      if (lap.started === null || before >= lap.finish || car.angle < lap.finish) return;

      const fraction = (lap.finish - before) / (car.angle - before);
      const crossed = frameStart + (now - frameStart) * fraction;
      const elapsed = (crossed - lap.started) / 1000;
      if (lap.best === null || elapsed < lap.best) {
        lap.best = elapsed;
        try { localStorage.setItem(KEY, String(elapsed)); } catch {}
        ui.notice.textContent = `New best · ${format(elapsed)}`;
      } else {
        ui.notice.textContent = `Last lap · ${format(elapsed)}`;
      }
      lap.number++;
      lap.finish += TAU;
      lap.started = crossed;
    }

    function draw(dt, snap) {
      const p = point(car.angle, car.offset);
      const forward = new THREE.Vector3(
        -(A + car.offset) * Math.sin(car.angle), 0,
        (B + car.offset) * Math.cos(car.angle)
      ).normalize();
      model.position.copy(p);
      model.rotation.y = Math.atan2(forward.x, forward.z) + car.lateral * 0.04;
      const eye = p.clone().addScaledVector(forward, -10);
      eye.y = 6.7;
      camera.position.lerp(eye, snap ? 1 : 1 - Math.exp(-7 * dt));
      const aim = p.clone().addScaledVector(forward, 9);
      aim.y = 0.9;
      camera.lookAt(aim);
      renderer.render(scene, camera);
    }

    function resize() {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    }
    addEventListener("resize", resize);
    resize();

    let last = null;
    function frame(now) {
      const frameStart = last ?? now;
      const dt = Math.min((now - frameStart) / 1000, 0.05);
      const snap = last === null || restartRequested;
      last = now;
      if (restartRequested) {
        restartRequested = false;
        reset();
      } else if (!document.hidden) {
        const before = car.angle;
        drive(dt);
        updateLap(before, frameStart, now);
      }

      ui.lap.textContent = lap.number;
      ui.time.textContent = format(lap.started === null ? 0 : (now - lap.started) / 1000);
      ui.best.textContent = lap.best === null ? "--:--.---" : format(lap.best);
      ui.speed.textContent = `${Math.round(Math.abs(car.speed) * 3.6)} km/h`;
      draw(dt, snap);
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  </script>
</body>
</html>
