    const crown = new THREE.ConeGeometry(1.4, 3.5, 5);
    const bark = material(0x76503b);
    const greens = [material(0x244f40), material(0x396f4a), material(0x528352)];
    for (let i = 0; i < 70; i++) {
      const { point, right } = trackAt(i * length / 70);
      point.addScaledVector(right, (i % 2 ? 1 : -1) * (9 + (i * 7 % 5)));
      const tree = new THREE.Group();
      tree.position.copy(point);
      tree.scale.setScalar(0.75 + (i * 13 % 9) / 12);
      tree.rotation.y = i * 2.4;
      scene.add(tree);
      mesh(tree, trunk, bark, 0, 0.6, 0);
      mesh(tree, crown, greens[i % 3], 0, 2.5, 0);
    }

    const car = new THREE.Group();
    scene.add(car);
    mesh(car, new THREE.BoxGeometry(1.65, 0.44, 2.85), material(0xf4a52c), 0, 0.51, 0);
    mesh(car, new THREE.BoxGeometry(1.22, 0.46, 1.30), material(0x214453), 0, 0.92, -0.25);
    mesh(car, new THREE.BoxGeometry(1.56, 0.12, 0.36), chalk, 0, 0.86, -1.27);
    const tire = new THREE.CylinderGeometry(0.32, 0.32, 0.25, 10);
    for (const x of [-0.83, 0.83]) {
      for (const z of [-0.94, 0.94]) {
        mesh(car, tire, dark, x, 0.33, z).rotation.z = Math.PI / 2;
      }
    }

    const storageKey = 'pine-loop.best.v1';
    function loadBest() {
      try {
        const value = Number(localStorage.getItem(storageKey));
        return Number.isFinite(value) && value > 0 ? value : null;
      } catch {
        return null;
      }
    }

    const drive = { distance: 0, offset: 0, speed: 0, steer: 0 };
    const laps = { start: null, nextFinish: length, number: 1, best: loadBest() };
    const held = new Set();
    const controls = new Set([
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp',
      'ArrowLeft', 'ArrowDown', 'ArrowRight', 'KeyR'
    ]);
    const pressed = (a, b) => held.has(a) || held.has(b);

    function reset() {
      Object.assign(drive, { distance: 0, offset: 0, speed: 0, steer: 0 });
      Object.assign(laps, { start: null, nextFinish: length, number: 1 });
      held.clear();
      $('status').textContent = 'Press accelerate to start.';
      pose(0, true);
    }

    addEventListener('keydown', event => {
      if (!controls.has(event.code)) return;
      event.preventDefault();
      if (event.code === 'KeyR') {
        if (!event.repeat) reset();
      } else {
        held.add(event.code);
      }
    });
    addEventListener('keyup', event => held.delete(event.code));
    addEventListener('blur', () => held.clear());
    document.addEventListener('visibilitychange', () => held.clear());

    function updateLap(previous, now) {
      if (laps.start === null || previous >= laps.nextFinish ||
          drive.distance < laps.nextFinish) return;
      const elapsed = now - laps.start;
      const record = laps.best === null || elapsed < laps.best;
      if (record) {
        laps.best = elapsed;
        try { localStorage.setItem(storageKey, String(elapsed)); } catch {}
      }
      laps.start = now;
      laps.nextFinish += length;
      laps.number++;
      $('status').textContent = `${record ? 'New best' : 'Last lap'} · ${format(elapsed)}`;
    }

    function step(dt, now) {
      const throttle = pressed('KeyW', 'ArrowUp');
      const brake = pressed('KeyS', 'ArrowDown');
      const steering = Number(pressed('KeyD', 'ArrowRight')) -
                       Number(pressed('KeyA', 'ArrowLeft'));
      if (laps.start === null && (throttle || brake)) {
        laps.start = now;
        $('status').textContent = 'Time trial running';
      }

      const pace = brake ? (drive.speed > 0 ? -46 : -11) : throttle ? 19 : 0;
      drive.speed += pace * dt;
      drive.speed *= Math.exp(-(throttle || brake ? 0.24 : 1.45) * dt);
      drive.speed = THREE.MathUtils.clamp(drive.speed, -9, 35);
      if (Math.abs(drive.speed) < 0.04) drive.speed = 0;
      drive.steer = THREE.MathUtils.lerp(drive.steer, steering, 1 - Math.exp(-12 * dt));
      const offset = drive.offset + drive.steer * drive.speed * 0.25 * dt;
      const edge = halfWidth - 0.87;
      drive.offset = THREE.MathUtils.clamp(offset, -edge, edge);
      if (offset !== drive.offset) drive.speed *= Math.exp(-2.5 * dt);

      const previous = drive.distance;
      drive.distance += drive.speed * dt;
      updateLap(previous, now);
    }

    const cameraGoal = new THREE.Vector3();
    const look = new THREE.Vector3();
    function pose(dt, snap = false) {
      const { point, forward, right } = trackAt(drive.distance);
      car.position.copy(point).addScaledVector(right, drive.offset);
      car.rotation.y = Math.atan2(forward.x, forward.z) - 0.22 * drive.steer;
      cameraGoal.copy(car.position).addScaledVector(forward, -8.5);
      cameraGoal.y += 5.2;
      camera.position.lerp(cameraGoal, snap ? 1 : 1 - Math.exp(-9 * dt));
      look.copy(car.position).addScaledVector(forward, 5);
      look.y += 0.65;
      camera.lookAt(look);
    }

    function format(ms) {
      const n = Math.floor(ms);
      const seconds = String(Math.floor(n / 1000) % 60).padStart(2, '0');
      return `${Math.floor(n / 60000)}:${seconds}.${String(n % 1000).padStart(3, '0')}`;
    }

    function resize() {
      camera.aspect = innerWidth / innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(innerWidth, innerHeight);
    }

    addEventListener('resize', resize);
    resize();
    reset();
    let previousFrame = performance.now();
    renderer.setAnimationLoop(now => {
      const dt = Math.min(0.05, Math.max(0, (now - previousFrame) / 1000));
      previousFrame = now;
      step(dt, now);
      pose(dt);
      $('lap').textContent = laps.number;
      $('current').textContent = format(laps.start === null ? 0 : now - laps.start);
      $('best').textContent = laps.best === null ? '–' : format(laps.best);
      $('speed').textContent = `${Math.round(Math.abs(drive.speed) * 3.6)} km/h`;
      renderer.render(scene, camera);
    });
  </script>
</body>
</html>
```

### Run and verify

From the folder containing `index.html`, run `python3 -m http.server 8000` locally and open `http://localhost:8000/`. The browser needs WebGL and internet access to load Three.js.

1. **Load and drive.** Check that the road, car, and HUD appear without console errors. Hold **W**. The timer and speed should rise, and the camera should follow the car. Check both steering directions and hold **S** until the car reverses.
2. **Complete a lap.** Hold **W** to follow the circuit. At the checkered line, the lap should advance to 2, the current timer should restart, and the best lap should appear. Drive a second lap with a deliberate stop. It should report the slower lap without replacing the best.
3. **Try to fool the lap counter.** Press **R**, reverse across the starting stripe, then drive forward across it. The counter should stay on lap 1 until you complete the full forward circuit.
4. **Check reset and persistence.** Press **R** mid-lap. The car should return to the start and the current clock should reset, while the best remains. Reload on the same origin and confirm the best still appears.
5. **Check the browser edges.** Resize to a narrow window and confirm the HUD remains readable. Switch tabs while holding a key, release it, and return. The key should not remain stuck. The lap clock counts time spent away from the tab.

Save the code below as `index.html`. It contains a low-poly time trial with one closed circuit, a chase camera, keyboard controls, and a best lap that persists when browser storage is available. There is no build step. The page loads a pinned Three.js version from a CDN, so it needs an internet connection.

**Design and data shape.** One track model defines the road mesh, the driving boundary, and the timing gates. The car holds position, heading, and speed. The lap state holds unwrapped track progress, the next forward gate, the current lap's start time, and the best lap. **Model the domain** led to the ordered gates rather than a finish-line-only counter. **Prove it works** led to the browser checks below, including reverse crossings and focus loss. I reviewed the code by inspection but did not run it.

