    <dt>Time</dt><dd id="time">0:00.000</dd>
    <dt>Best</dt><dd id="best">--:--.---</dd>
    <dt>Speed</dt><dd id="speed">0 km/h</dd>
  </dl>
  <p id="status" role="status">Accelerate to start</p>
</section>
<p id="help">WASD or arrow keys to drive · R to restart</p>

<script type="module">
const status = document.querySelector('#status');
try {
  const THREE = await import(
    'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js'
  );
  start(THREE);
} catch (error) {
  status.textContent = 'Could not start. Check your internet connection and WebGL support.';
  console.error(error);
}

function start(T) {
  const TAU = Math.PI * 2;
  const HALF = 5;
  const STORAGE_KEY = 'sunset-circuit-best-v1';
  const clamp = T.MathUtils.clamp;
  const radius = a => 49 + 7 * Math.cos(2 * a) + 4 * Math.sin(3 * a);
  const scene = new T.Scene();
  scene.background = new T.Color(0xf6bc88);
  scene.fog = new T.FogExp2(0xf6bc88, 0.0065);
  const camera = new T.PerspectiveCamera(62, 1, 0.1, 320);
  const renderer = new T.WebGLRenderer({ antialias: true });
  document.body.append(renderer.domElement);
  scene.add(new T.HemisphereLight(0xffebcc, 0x657d63, 2.1));
  const sun = new T.DirectionalLight(0xffd49e, 2.3);
  sun.position.set(-40, 65, -25);
  scene.add(sun);

  function material(color) {
    return new T.MeshStandardMaterial({ color, flatShading: true });
  }

  function mesh(geometry, paint, x, y, z, parent = scene) {
    const object = new T.Mesh(geometry, paint);
    object.position.set(x, y, z);
    parent.add(object);
    return object;
  }

  function box(w, h, d, paint, x, y, z, parent = scene) {
    return mesh(new T.BoxGeometry(w, h, d), paint, x, y, z, parent);
  }

  const ground = mesh(new T.PlaneGeometry(600, 600), material(0x75894a), 0, -0.04, 0);
  ground.rotation.x = -Math.PI / 2;

  function strip(inner, outer, y, color, start = 0, end = TAU, segments = 384) {
    const vertices = [], indices = [];
    for (let i = 0; i <= segments; i++) {
      const a = start + (end - start) * i / segments;
      for (const offset of [inner, outer]) {
        const r = radius(a) + offset;
        vertices.push(r * Math.cos(a), y, r * Math.sin(a));
      }
      if (i < segments) {
        const j = 2 * i;
        indices.push(j, j + 2, j + 1, j + 1, j + 2, j + 3);
      }
    }
    const geometry = new T.BufferGeometry();
    geometry.setAttribute('position', new T.Float32BufferAttribute(vertices, 3));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    mesh(geometry, material(color), 0, 0, 0);
  }

  strip(-HALF - 0.65, HALF + 0.65, 0, 0xa36846);
  strip(-HALF, HALF, 0.02, 0x303840);
  strip(-HALF, -HALF + 0.18, 0.03, 0xffe7bd);
  strip(HALF - 0.18, HALF, 0.03, 0xffe7bd);
  for (let i = 0; i < 56; i++) {
    const a = TAU * (i + 0.4) / 56;
    strip(-0.08, 0.08, 0.031, 0xbcaa87, a, a + 0.04, 3);
  }

  const cream = material(0xffeed0);
  const dark = material(0x17232a);
  for (let x = 0; x < 10; x++) {
    for (let z = 0; z < 2; z++) {
      box(1, 0.016, 0.55, (x + z) % 2 ? cream : dark,
          radius(0) - HALF + x + 0.5, 0.04, (z - 0.5) * 0.55);
    }
  }

  let seed = 83;
  function random() {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  }
  const trunk = material(0x654636);
  const leaves = [material(0x314f40), material(0x486b48)];
  const crown = new T.ConeGeometry(1.55, 3.7, 5);
  for (let i = 0; i < 125; i++) {
    const a = random() * TAU;
    const r = 15 + random() * 115;
    if (Math.abs(r - radius(a)) < 10) continue;
    const x = r * Math.cos(a), z = r * Math.sin(a);
    const s = 0.65 + random() * 1.1;
    box(0.45 * s, 1.5 * s, 0.45 * s, trunk, x, 0.75 * s, z);
    const tree = mesh(crown, leaves[i % 2], x, 2.7 * s, z);
    tree.scale.setScalar(s);
    tree.rotation.y = a;
  }

  const car = new T.Group();
  scene.add(car);
  const coral = material(0xf05d43);
  const glass = material(0x284756);
  box(1.85, 0.52, 3.45, coral, 0, 0.56, 0, car);
  box(1.42, 0.53, 1.52, glass, 0, 1.02, -0.20, car);
  box(1.48, 0.10, 1.25, coral, 0, 1.33, -0.27, car);
  box(1.85, 0.12, 0.32, dark, 0, 1.04, -1.49, car);
  const wheel = new T.CylinderGeometry(0.36, 0.36, 0.32, 10);
  for (const x of [-0.96, 0.96]) {
    for (const z of [-1.05, 1.05]) {
      mesh(wheel, dark, x, 0.37, z, car).rotation.z = Math.PI / 2;
    }
    box(0.43, 0.16, 0.08, cream, x * 0.69, 0.61, 1.74, car);
  }

  const shadow = mesh(
    new T.CircleGeometry(1, 16),
    new T.MeshBasicMaterial({ color: 0x111a18, transparent: true, opacity: 0.28 }),
    0, 0.055, 0
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(1.22, 2.03, 1);

  const hud = Object.fromEntries(
    ['lap', 'time', 'best', 'speed'].map(id => [id, document.getElementById(id)])
  );
  const keys = new Set();
  const controls = new Set([
    'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowLeft',
    'ArrowDown', 'ArrowRight', 'KeyR'
  ]);
  const drive = (a, b) => keys.has(a) || keys.has(b);
  let best = Infinity;
  try {
    const value = Number(localStorage.getItem(STORAGE_KEY));
    if (Number.isFinite(value) && value > 0) best = value;
  } catch {}

  const pose = {};
  const lap = {};
  const eye = new T.Vector3();
  const focus = new T.Vector3();

  function reset() {
    Object.assign(pose, {
      x: radius(0), z: 0, heading: Math.atan2(12, radius(0)), speed: 0
    });
    Object.assign(lap, {
      number: 1, elapsed: 0, angle: 0, progress: 0, phase: 'ready'
    });
    camera.position.set(pose.x - 3, 6, -10);
  }

  window.addEventListener('keydown', event => {
    if (!controls.has(event.code)) return;
    event.preventDefault();
    if (event.code === 'KeyR' && !event.repeat) reset();
    keys.add(event.code);
  });
  window.addEventListener('keyup', event => keys.delete(event.code));
  window.addEventListener('blur', () => keys.clear());
  document.addEventListener('visibilitychange', () => {
    keys.clear();
    lastFrame = null;
  });

  function resize() {
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);

  function roadOffset(x, z) {
    return Math.abs(Math.hypot(x, z) - radius(Math.atan2(z, x)));
  }

  function tick(dt) {
    const throttle = Number(drive('KeyW', 'ArrowUp')) -
                     Number(drive('KeyS', 'ArrowDown'));
    const steer = Number(drive('KeyA', 'ArrowLeft')) -
                  Number(drive('KeyD', 'ArrowRight'));
    const offRoad = roadOffset(pose.x, pose.z) > HALF;
    const topSpeed = offRoad ? 12 : 33;
    const acceleration = throttle * (throttle * pose.speed < 0 ? 38 : 20);
    pose.speed += acceleration * dt;
    pose.speed *= Math.exp(-(offRoad ? 2.0 : throttle ? 0.22 : 0.9) * dt);
    pose.speed = clamp(pose.speed, -9, topSpeed);
    pose.heading += steer * 1.65 * clamp(pose.speed / 7, -1, 1) * dt;
    pose.x += Math.sin(pose.heading) * pose.speed * dt;
    pose.z += Math.cos(pose.heading) * pose.speed * dt;

    const angle = Math.atan2(pose.z, pose.x);
    const delta = angle - lap.angle;
    const step = Math.atan2(Math.sin(delta), Math.cos(delta));
    lap.angle = angle;

    if (lap.phase === 'ready' && throttle !== 0) lap.phase = 'running';
    if (lap.phase === 'ready') return;

    // Leave room for a wide turn, but do not count a lap that cuts across the infield.
    if (roadOffset(pose.x, pose.z) > HALF + 3) lap.phase = 'invalid';
    lap.progress += step;
    lap.elapsed += dt;
    if (lap.progress < TAU) return;

    const overshoot = step > 0 ? dt * (lap.progress - TAU) / step : 0;
    if (lap.phase === 'running') {
      const result = lap.elapsed - overshoot;
      if (result < best) {
        best = result;
        try { localStorage.setItem(STORAGE_KEY, String(best)); } catch {}
      }
      lap.number++;
    }
    lap.progress -= TAU;
    lap.elapsed = overshoot;
    lap.phase = roadOffset(pose.x, pose.z) <= HALF + 3 ? 'running' : 'invalid';
  }

  function format(seconds) {
    if (!Number.isFinite(seconds)) return '--:--.---';
    const ms = Math.floor(seconds * 1000);
    return `${Math.floor(ms / 60000)}:${String(Math.floor(ms / 1000) % 60)
      .padStart(2, '0')}.${String(ms % 1000).padStart(3, '0')}`;
  }

  function draw(dt) {
    const x = Math.sin(pose.heading), z = Math.cos(pose.heading);
    car.position.set(pose.x, 0.04, pose.z);
    car.rotation.y = pose.heading;
    shadow.position.set(pose.x, 0.055, pose.z);
    shadow.rotation.z = pose.heading;
    eye.set(pose.x - x * 9.6, 5.5, pose.z - z * 9.6);
    focus.set(pose.x + x * 5.5, 0.8, pose.z + z * 5.5);
    camera.position.lerp(eye, 1 - Math.exp(-7 * dt));
    camera.lookAt(focus);

    hud.lap.textContent = lap.number;
    hud.time.textContent = format(lap.elapsed);
    hud.best.textContent = format(best);
    hud.speed.textContent = `${Math.round(Math.abs(pose.speed) * 3.6)} km/h`;
    const message = {
      ready: 'Accelerate to start',
      running: 'Lap in progress',
      invalid: 'Lap invalid · finish the circuit or press R'
    }[lap.phase];
    if (status.textContent !== message) status.textContent = message;
    renderer.render(scene, camera);
  }

  let lastFrame = null;
  function frame(now) {
    const dt = lastFrame === null ? 0 : Math.min((now - lastFrame) / 1000, 0.1);
    lastFrame = now;
    const steps = Math.max(1, Math.ceil(dt * 120));
    for (let i = 0; i < steps; i++) tick(dt / steps);
    draw(dt);
    requestAnimationFrame(frame);
  }

  resize();
  reset();
  requestAnimationFrame(frame);
}
</script>
</body>
</html>
