  <script type="module">
    import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

    const track = { radius: 44, halfWidth: 5, shoulderLimit: 9, segments: 96 };
    const length = 2 * Math.PI * track.radius;
