    /^(?:\s*[=+\-@]|[\t\r\n])/u.test(text)
  ) {
    text = "'" + text;
  }

  return `"${text.replace(/"/g, '""')}"`;
}

function download(blob: Blob, name: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  document.body.appendChild(link);
  link.click();
  link.remove();

  // Give the browser time to start consuming the URL.
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

export default function ReportExportButtons<Row>({
  rows,
  columns,
  filename = "report",
  title = "Report",
}: Props<Row>) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState("");

  async function exportReport(format: Format) {
    setBusy(format);
    setError("");

    try {
      const name = `${filename}.${format}`;
      const headers = columns.map((column) => column.header);
      const body = rows.map((row) =>
        columns.map((column) => column.value(row)),
      );

      if (format === "csv") {
        const csv = [headers, ...body]
          .map((row) => row.map(csvCell).join(","))
          .join("\r\n");

        // The UTF-8 BOM helps desktop Excel recognize non-ASCII text.
        download(new Blob(["\uFEFF", csv], {
          type: "text/csv;charset=utf-8",
        }), name);
      } else if (format === "xlsx") {
        const { Workbook } = await import("exceljs");
        const workbook = new Workbook();
        const sheet = workbook.addWorksheet("Report", {
          views: [{ state: "frozen", ySplit: 1 }],
        });

        sheet.addRow(headers).font = { bold: true };
        sheet.addRows(
          body.map((row) =>
            row.map((value) =>
              value instanceof Date ? cellText(value) : value ?? null,
            ),
          ),
        );

        headers.forEach((header, index) => {
          sheet.getColumn(index + 1).width = Math.min(
            Math.max(header.length + 4, 16),
            48,
          );
        });

        const buffer = await workbook.xlsx.writeBuffer();
        download(new Blob([buffer], {
          type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        }), name);
      } else {
        const [{ jsPDF }, { autoTable }] = await Promise.all([
          import("jspdf"),
          import("jspdf-autotable"),
        ]);
        const doc = new jsPDF({ orientation: "landscape" });
        doc.setFontSize(16);
        doc.text(title, 14, 16);

        autoTable(doc, {
          startY: 22,
          head: [headers],
          body: body.map((row) => row.map(cellText)),
          showHead: "everyPage",
          horizontalPageBreak: true,
          styles: { fontSize: 9, overflow: "linebreak" },
        });

        doc.save(name);
      }
    } catch (err) {
      console.error("Report export failed", err);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report">
      {(["csv", "xlsx", "pdf"] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
          {busy === format ? "Exporting…" : `Export ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
