  return `"${text.replace(/"/g, '""')}"`;
}

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  try {
    link.click();
  } finally {
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
  }
}

export function ReportExport<Row>({
  rows,
  columns,
  filename = "report",
  title = "Report",
}: Props<Row>) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState("");

  async function exportReport(format: Format) {
    setBusy(format);
    setError("");

    try {
      const headers = columns.map((column) => column.header);
      const data = rows.map((row) =>
        columns.map((column) => column.value(row)),
      );

      if (format === "csv") {
        const csv = [headers, ...data]
          .map((row) => row.map(csvField).join(","))
          .join("\r\n");

        // The BOM helps Excel recognize UTF-8.
        download(
          new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }),
          `${filename}.csv`,
        );
      } else if (format === "xlsx") {
        const { default: ExcelJS } = await import("exceljs");
        const workbook = new ExcelJS.Workbook();
        const sheet = workbook.addWorksheet("Report");

        sheet.addRow(headers).font = { bold: true };
        sheet.views = [{ state: "frozen", ySplit: 1 }];

        columns.forEach((column, index) => {
          sheet.getColumn(index + 1).width = Math.min(
            50,
            Math.max(14, column.header.length + 4),
          );
        });

        for (const row of data) {
          // Keep numbers and booleans typed, and use the same UTC date
          // representation as CSV and PDF. Strings are not formulas.
          sheet.addRow(
            row.map((value) => (value instanceof Date ? cellText(value) : value ?? null)),
          );
        }

        const buffer = await workbook.xlsx.writeBuffer();
        download(
          new Blob([buffer], {
            type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
          }),
          `${filename}.xlsx`,
        );
      } else {
        const [{ jsPDF }, { autoTable }] = await Promise.all([
          import("jspdf"),
          import("jspdf-autotable"),
        ]);

        const doc = new jsPDF({ orientation: "landscape", unit: "mm" });
        doc.setFontSize(16);
        doc.text(title, 14, 15);

        autoTable(doc, {
          startY: 21,
          head: [headers],
          body: data.map((row) => row.map(cellText)),
          showHead: "everyPage",
          horizontalPageBreak: true,
          styles: { fontSize: 9, overflow: "linebreak" },
        });

        doc.save(`${filename}.pdf`);
      }
    } catch (cause) {
      console.error(`Report ${format} export failed`, cause);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report" aria-busy={busy !== null}>
      {(["csv", "xlsx", "pdf"] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
          {busy === format ? "Exporting…" : `Export ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
