```tsx
// app/reports/ReportExport.tsx
'use client';

import { useState } from 'react';

type Cell = string | number | boolean | Date | null | undefined;
type Format = 'csv' | 'xlsx' | 'pdf';

export type ExportColumn<Row> = {
  header: string;
  value: (row: Row) => Cell;
};

function toText(value: Cell): string {
  return value instanceof Date ? value.toISOString() : String(value ?? '');
}

function csvField(value: Cell): string {
  let text = toText(value);

  // Prevent spreadsheet apps from interpreting untrusted text as formulas.
  // Keep actual numeric values, including negative numbers, unchanged.
  if (typeof value === 'string' && /^(?:\s*[=+\-@]|[\t\r\n])/u.test(text)) {
    text = `'${text}`;
  }

  return `"${text.replace(/"/g, '""')}"`;
}

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

export default function ReportExport<Row>({
  rows,
  columns,
  filename = 'report',
}: {
  rows: readonly Row[];
  columns: readonly ExportColumn<Row>[];
  filename?: string;
}) {
  const [busy, setBusy] = useState<Format | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function exportReport(format: Format) {
    setBusy(format);
    setError(null);

    try {
      const headers = columns.map(({ header }) => header);
      const data = rows.map((row) => columns.map(({ value }) => value(row)));

      switch (format) {
        case 'csv': {
          const csv = [headers, ...data]
            .map((row) => row.map(csvField).join(','))
            .join('\r\n');

          // The BOM helps Excel recognize UTF-8.
          download(
            new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }),
            `${filename}.csv`,
          );
          break;
        }

        case 'xlsx': {
          const { default: ExcelJS } = await import('exceljs');
          const workbook = new ExcelJS.Workbook();
          const sheet = workbook.addWorksheet('Report');

          sheet.addRow(headers).font = { bold: true };
          sheet.views = [{ state: 'frozen', ySplit: 1 }];

          for (const row of data) {
            // Store dates as ISO text so their time zone is unambiguous.
            // Numbers and booleans remain native spreadsheet values.
            sheet.addRow(
              row.map((value) =>
                value instanceof Date ? value.toISOString() : (value ?? null),
              ),
            );
          }

          const buffer = await workbook.xlsx.writeBuffer();
          download(
            new Blob([new Uint8Array(buffer)], {
              type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            }),
            `${filename}.xlsx`,
          );
          break;
        }

        case 'pdf': {
          const [{ jsPDF }, { autoTable }] = await Promise.all([
            import('jspdf'),
            import('jspdf-autotable'),
          ]);
          const doc = new jsPDF({ orientation: 'landscape' });

          autoTable(doc, {
            head: [headers],
            body: data.map((row) => row.map(toText)),
            showHead: 'everyPage',
            horizontalPageBreak: true,
            styles: { fontSize: 9, overflow: 'linebreak' },
          });

          download(doc.output('blob'), `${filename}.pdf`);
          break;
        }
      }
    } catch (cause) {
      console.error('Report export failed', cause);
      setError(`Could not export ${format.toUpperCase()}. Please try again.`);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div role="group" aria-label="Export report">
      {(['csv', 'xlsx', 'pdf'] as const).map((format) => (
        <button
          key={format}
          type="button"
          disabled={busy !== null || columns.length === 0}
          onClick={() => void exportReport(format)}
        >
          {busy === format ? 'Exporting…' : `Export ${format.toUpperCase()}`}
        </button>
      ))}
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
