```tsx
// ReportsExport.tsx
'use client';

import { useRef, useState } from 'react';

type Row = Record<string, unknown>;
type Column = { key: string; label: string };

function download(filename: string, blob: Blob) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1_000);
}

function cell(value: unknown): string | number | boolean {
  if (value == null) return '';
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  if (value instanceof Date) return value.toISOString();
  return String(value);
}

function csvCell(value: string | number | boolean) {
  // Keep user-provided text from being interpreted as a spreadsheet formula.
  const text =
    typeof value === 'string' && /^(?:\s*[=+\-@]|[\t\r\n])/.test(value)
      ? `'${value}`
      : String(value);

  return `"${text.replace(/"/g, '""')}"`;
}

export default function ReportsExport({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly Column[];
}) {
  const printTable = useRef<HTMLTableElement>(null);
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState('');

  const headers = () => columns.map(({ label }) => label);
  const values = (row: Row) => columns.map(({ key }) => cell(row[key]));

  function exportCsv() {
    const csv = [headers(), ...rows.map(values)]
      .map((row) => row.map(csvCell).join(','))
      .join('\r\n');

    download('reports.csv', new Blob(['\uFEFF', csv], {
      type: 'text/csv;charset=utf-8',
    }));
  }

  async function exportXlsx() {
    setExporting(true);
    setError('');
    try {
      const { Workbook } = await import('exceljs');
      const workbook = new Workbook();
      const sheet = workbook.addWorksheet('Reports');
      sheet.addRow(headers());
      for (const row of rows) sheet.addRow(values(row));
      sheet.getRow(1).font = { bold: true };

      const buffer = await workbook.xlsx.writeBuffer();
      download('reports.xlsx', new Blob([new Uint8Array(buffer)], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      }));
    } catch {
      setError('Could not export XLSX. Please try again.');
    } finally {
      setExporting(false);
    }
  }

  function exportPdf() {
    setError('');
    const popup = window.open('', '_blank', 'popup');
    if (!popup) {
      setError('Allow pop-ups for this site to export PDF.');
      return;
    }

    popup.opener = null;
    popup.document.title = 'Reports';
    const style = popup.document.createElement('style');
    style.textContent = `
      @page { size: landscape; margin: 12mm; }
      body { font: 11pt system-ui, sans-serif; }
      table { width: 100%; border-collapse: collapse; }
      thead { display: table-header-group; }
      tr { break-inside: avoid; }
      th, td { border: 1px solid #bbb; padding: 5px; text-align: left;
               overflow-wrap: anywhere; }
    `;
    popup.document.head.append(style);
    popup.document.body.append(popup.document.importNode(printTable.current!, true));
    popup.focus();
    popup.print();
  }

  return (
    <>
      <button type="button" onClick={exportCsv}>Download CSV</button>
      <button type="button" onClick={exportXlsx} disabled={exporting}>
        {exporting ? 'Exporting…' : 'Download XLSX'}
      </button>
      <button type="button" onClick={exportPdf}>Save as PDF</button>
      {error && <p role="alert">{error}</p>}

      <div hidden>
        <table ref={printTable}>
          <thead>
            <tr>{columns.map(({ key, label }) => <th key={key}>{label}</th>)}</tr>
          </thead>
          <tbody>
            {rows.map((row, index) => (
              <tr key={index}>
                {columns.map(({ key }) => <td key={key}>{String(cell(row[key]))}</td>)}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}
