    const headers = columns.map(({ label }) => label);
    const values = rows.map((row) => columns.map(({ key }) => row[key]));

    if (format === "csv") {
      const csv = [headers, ...values]
        .map((row) => row.map(csvCell).join(","))
        .join("\r\n");
