// ReportExport.tsx
'use client';

type Cell = string | number | boolean | null | undefined;
type Column<Row> = { label: string; value: (row: Row) => Cell };
type Format = 'csv' | 'xlsx' | 'pdf';

function csvCell(value: Cell) {
  const text = String(value ?? '');
  // Prevent spreadsheet apps from interpreting user-provided text as formulas.
  const safe =
    typeof value === 'string' && /^[\s\uFEFF]*[=+\-@]|^[\t\r\n]/.test(text)
      ? `'${text}`
      : text;
  return `"${safe.replace(/"/g, '""')}"`;
}

function download(filename: string, blob: Blob) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 30_000);
}

export function ReportExport<Row>({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly Column<Row>[];
}) {
  async function exportReport(format: Format) {
    const headers = columns.map((column) => column.label);
    const data = rows.map((row) => columns.map((column) => column.value(row)));

    if (format === 'csv') {
      const csv = [headers, ...data]
        .map((row) => row.map(csvCell).join(','))
        .join('\r\n');
      download('report.csv', new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }));
      return;
    }

    if (format === 'xlsx') {
      const { Workbook } = await import('exceljs');
      const workbook = new Workbook();
      const sheet = workbook.addWorksheet('Report');
      sheet.addRow(headers).font = { bold: true };
      for (const row of data) sheet.addRow(row.map((value) => value ?? null));
      const bytes = await workbook.xlsx.writeBuffer();
      download(
        'report.xlsx',
        new Blob([new Uint8Array(bytes)], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        }),
      );
      return;
    }

    const popup = window.open('', '_blank');
    if (!popup) throw new Error('Allow pop-ups to print or save this report as PDF.');
    popup.opener = null;

    const doc = popup.document;
    doc.title = 'Report';
    const style = doc.createElement('style');
    style.textContent = `
      body { font: 12px system-ui, sans-serif; }
      table { width: 100%; border-collapse: collapse; }
      th, td { border: 1px solid #aaa; padding: 6px; text-align: left; overflow-wrap: anywhere; }
      thead { display: table-header-group; }
      tr { break-inside: avoid; }
    `;
    doc.head.append(style);

    const table = doc.createElement('table');
    const header = table.createTHead().insertRow();
    for (const label of headers) {
      const cell = doc.createElement('th');
      cell.scope = 'col';
      cell.textContent = label;
      header.append(cell);
    }

    const body = table.createTBody();
    for (const row of data) {
      const tr = body.insertRow();
      for (const value of row) tr.insertCell().textContent = String(value ?? '');
    }
    doc.body.append(table);
    popup.focus();
    popup.print();
  }

  return (
    <div>
      {(['csv', 'xlsx', 'pdf'] as const).map((format) => (
        <button
          key={format}
          type="button"
          onClick={() => {
            void exportReport(format).catch((error: unknown) => {
              window.alert(error instanceof Error ? error.message : 'Export failed.');
            });
          }}
        >
          {format === 'pdf' ? 'Print / Save PDF' : `Download ${format.toUpperCase()}`}
        </button>
      ))}
    </div>
  );
}
