'use client';

type ReportRow = Record<string, unknown>;
type ReportColumn = { key: string; label: string };

function cellText(value: unknown) {
  if (value == null) return '';
  if (value instanceof Date) return value.toISOString();
  return typeof value === 'object'
    ? (JSON.stringify(value) ?? '')
    : String(value);
}

function csvCell(value: unknown) {
  const text = cellText(value);
  // Keep user-controlled text from being interpreted as a spreadsheet formula.
  const safe =
    typeof value !== 'number' && /^[\s\uFEFF]*[=+\-@\t\r\n]/u.test(text)
      ? `'${text}`
      : text;
  return `"${safe.replace(/"/g, '""')}"`;
}

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function ReportExports({
  rows,
  columns,
}: {
  rows: ReportRow[];
  columns: ReportColumn[];
}) {
  function exportCsv() {
    const csv = [
      columns.map(({ label }) => csvCell(label)).join(','),
      ...rows.map((row) => columns.map(({ key }) => csvCell(row[key])).join(',')),
    ].join('\r\n');

    download(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }), 'reports.csv');
  }

  async function exportXlsx() {
    try {
      const { Workbook } = await import('exceljs');
      const workbook = new Workbook();
      const sheet = workbook.addWorksheet('Reports');

      sheet.addRow(columns.map(({ label }) => label));
      for (const row of rows) {
        sheet.addRow(
          columns.map(({ key }) => {
            const value = row[key];
            return typeof value === 'number' || typeof value === 'boolean'
              ? value
              : cellText(value);
          }),
        );
      }

      const buffer = await workbook.xlsx.writeBuffer();
      download(
        new Blob([new Uint8Array(buffer)], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        }),
        'reports.xlsx',
      );
    } catch {
      window.alert('Could not export the report as XLSX. Please try again.');
    }
  }

  function exportPdf() {
    const preview = window.open('about:blank', '_blank');
    if (!preview) {
      window.alert('Allow pop-ups for this site to export a PDF.');
      return;
    }
    preview.opener = null;

    const doc = preview.document;
    doc.title = 'Reports';
    const style = doc.createElement('style');
    style.textContent = `
      body { font: 12px system-ui, sans-serif; }
      table { width: 100%; border-collapse: collapse; table-layout: fixed; }
      th, td { border: 1px solid #aaa; padding: 6px; text-align: left;
               vertical-align: top; overflow-wrap: anywhere; }
      thead { display: table-header-group; }
      tr { break-inside: avoid; }
      @media print { button { display: none; } }
    `;
    doc.head.append(style);

    const print = doc.createElement('button');
    print.textContent = 'Print / Save as PDF';
    print.onclick = () => preview.print();

    const heading = doc.createElement('h1');
    heading.textContent = 'Reports';
    const table = doc.createElement('table');
    const header = table.createTHead().insertRow();
    for (const { label } of columns) {
      const th = doc.createElement('th');
      th.scope = 'col';
      th.textContent = label;
      header.append(th);
    }

    const body = table.createTBody();
    for (const row of rows) {
      const tr = body.insertRow();
      for (const { key } of columns) {
        tr.insertCell().textContent = cellText(row[key]);
      }
    }

    doc.body.append(print, heading, table);
    preview.focus();
    preview.requestAnimationFrame(() => preview.print());
  }

  return (
    <div role="group" aria-label="Export reports">
      <button type="button" onClick={exportCsv}>Download CSV</button>
      <button type="button" onClick={exportXlsx}>Download XLSX</button>
      <button type="button" onClick={exportPdf}>Save as PDF</button>
    </div>
  );
}
