  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function cellText(value: unknown) {
  return value == null ? '' : value instanceof Date ? value.toISOString() : String(value);
}

function csvCell(value: unknown) {
  let text = cellText(value);
  // Keep untrusted text from being interpreted as a spreadsheet formula.
  if (typeof value === 'string' && /^(?:\s*[=+\-@]|[\t\r\n])/.test(text)) {
    text = "'" + text;
  }
  return `"${text.replace(/"/g, '""')}"`;
}

export default function ReportsExport({ headers, rows }: Props) {
  function exportCsv() {
    const csv = [headers, ...rows].map(row => row.map(csvCell).join(',')).join('\r\n');
    download(new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' }), 'reports.csv');
  }

  async function exportXlsx() {
    const { Workbook } = await import('exceljs');
    const workbook = new Workbook();
    const sheet = workbook.addWorksheet('Reports');
    sheet.addRow(headers);
    for (const row of rows) {
      sheet.addRow(row.map(value =>
        typeof value === 'number' || typeof value === 'boolean' || value instanceof Date
          ? value
          : cellText(value),
      ));
    }
    const buffer = await workbook.xlsx.writeBuffer();
    download(
      new Blob([new Uint8Array(buffer)], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      }),
      'reports.xlsx',
    );
  }

  function exportPdf() {
    // scoper: browser print dialog; use a PDF generator if direct downloads are required.
    const popup = window.open('', '_blank', 'popup');
    if (!popup) {
      window.alert('Allow pop-ups for this site to export a PDF.');
      return;
    }

    popup.opener = null;
    const doc = popup.document;
    doc.title = 'Reports';
    const style = doc.createElement('style');
    style.textContent = `
      body { font: 12px system-ui, sans-serif; }
      table { width: 100%; border-collapse: collapse; }
      th, td { border: 1px solid #bbb; padding: 6px; text-align: left; overflow-wrap: anywhere; }
      thead { display: table-header-group; }
      tr { break-inside: avoid; }
    `;
    doc.head.appendChild(style);

    const table = doc.createElement('table');
    const heading = table.createTHead().insertRow();
    for (const label of headers) {
      const th = doc.createElement('th');
      th.scope = 'col';
      th.textContent = label;
      heading.appendChild(th);
    }
    const body = table.createTBody();
    for (const row of rows) {
      const tr = body.insertRow();
      for (const value of row) tr.insertCell().textContent = cellText(value);
    }
    doc.body.appendChild(table);
    popup.focus();
    popup.print();
  }

  return (
    <div>
      <button type="button" onClick={exportCsv}>Download CSV</button>
      <button
        type="button"
        onClick={() => void exportXlsx().catch(() => window.alert('Could not export XLSX.'))}
      >
        Download XLSX
      </button>
      <button type="button" onClick={exportPdf}>Save as PDF</button>
    </div>
  );
}
