```tsx
// ReportsExport.tsx — place next to the reports page.
"use client";

import { useState } from "react";

type Column<Row> = {
  header: string;
  value: (row: Row) => string | number | boolean | null | undefined;
};

function download(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function csvCell(value: ReturnType<Column<never>["value"]>) {
  let text = String(value ?? "");
  // Prevent spreadsheet apps from treating untrusted strings as formulas.
  if (typeof value === "string" && /^[\s\uFEFF]*[=+\-@]|^[\t\r\n]/.test(text)) {
    text = `'${text}`;
  }
  return `"${text.replace(/"/g, '""')}"`;
}

export default function ReportsExport<Row>({
  rows,
  columns,
}: {
  rows: readonly Row[];
  columns: readonly Column<Row>[];
}) {
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState("");

  function csv() {
    const lines = [
      columns.map(({ header }) => csvCell(header)).join(","),
      ...rows.map((row) =>
        columns.map(({ value }) => csvCell(value(row))).join(","),
      ),
    ];
    download(
      new Blob(["\uFEFF", lines.join("\r\n")], {
        type: "text/csv;charset=utf-8",
      }),
      "reports.csv",
    );
  }

  async function xlsx() {
    setExporting(true);
    setError("");
    try {
      const { Workbook } = await import("exceljs");
      const workbook = new Workbook();
      const sheet = workbook.addWorksheet("Reports");
      sheet.addRow(columns.map(({ header }) => header));
      for (const row of rows) {
        sheet.addRow(columns.map(({ value }) => value(row) ?? null));
      }
      const bytes = await workbook.xlsx.writeBuffer();
      download(
        new Blob([new Uint8Array(bytes)], {
          type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        }),
        "reports.xlsx",
      );
    } catch {
      setError("Could not export XLSX. Please try again.");
    } finally {
      setExporting(false);
    }
  }

  return (
    <div className="reports-no-print" role="group" aria-label="Export reports">
      <button type="button" onClick={csv}>Download CSV</button>
      <button type="button" onClick={xlsx} disabled={exporting}>
        {exporting ? "Preparing XLSX…" : "Download XLSX"}
      </button>
      <button type="button" onClick={() => window.print()}>Save as PDF</button>
      {error && <p role="alert">{error}</p>}
    </div>
  );
}
